// FIX 2: HMAC with hard rejection — no soft pass on failure
const crypto = require('crypto');
const sig = ($json.headers?.['x-sevari-sig'] || '').trim();
const rawBody = JSON.stringify($json.body || $json);
const secret = $vars.SYNC_HMAC_SECRET || '';
const channel = $json.channel || 'api';
const isDemo = $json.is_demo === true;
const requiresHMAC = ['webhook', 'api', 'task'].includes(channel) && !isDemo;

if (!requiresHMAC) {
  return [{ ...$json, hmac_valid: true, hmac_required: false, hmac_checked: true }];
}

if (!sig) {
  // Hard stop — required but missing
  return [{ ...$json, hmac_valid: false, hmac_required: true, hmac_checked: true,
    hmac_error: 'signature_missing', hard_reject: true,
    reject_reason: 'HMAC signature required for this channel but not provided',
    reject_code: 401 }];
}

const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
const valid = sig === expected;

if (!valid) {
  return [{ ...$json, hmac_valid: false, hmac_required: true, hmac_checked: true,
    hmac_error: 'signature_invalid', hard_reject: true,
    reject_reason: 'HMAC signature invalid',
    reject_code: 403 }];
}

return [{ ...$json, hmac_valid: true, hmac_required: true, hmac_checked: true }];

function sanitise(v){if(v==null)return '';let s=String(v);s=s.replace(/\x00/g,'');if(s.length>50000)s=s.substring(0,50000)+'...[truncated]';return s;}
const s={...$json};
for(const f of ['subject','body','sender_name','sender_email','sender_mobile','category_hint','channel'])
  if(s[f]!==undefined) s[f]=sanitise(s[f]);
return [{...s, sanitised:true}];

// FIX 13: No demo fallback in production — fail explicitly on missing business_id
const crypto = require('crypto');
const source = $json;
const isTask = !!source.target_agent;
const isDemo = source.demo === true || source.no_external === true;

// In production: if no business_id and not demo, reject
if (!source.business_id && !isDemo) {
  return [{ ...$json, normalise_error: true, error: 'missing_business_id',
    reject_reason: 'business_id is required for all non-demo requests', reject_code: 400 }];
}

// Demo mode: allow BIZ-DEMO-001 only when demo flag is explicitly set
const businessId = source.business_id || (isDemo ? 'BIZ-DEMO-001' : null);
if (!businessId) {
  return [{ ...$json, normalise_error: true, error: 'no_business_id_resolved', reject_code: 400 }];
}

const prefix = isTask ? 'TSK-' : 'SVR-';
const enquiryId = prefix + Date.now().toString(36).toUpperCase() + '-' + crypto.randomBytes(3).toString('hex').toUpperCase();
const chainHashStart = crypto.createHash('sha256').update(enquiryId + new Date().toISOString()).digest('hex');

return [{
  enquiry_id: enquiryId,
  business_id: businessId,
  channel: source.channel || (source.target_agent ? 'task' : 'api'),
  subject: source.subject || '',
  body: source.body || source.message || '',
  sender_email: source.sender_email || source.from || '',
  sender_name: source.sender_name || source.name || '',
  target_agent: source.target_agent || null,
  is_task: isTask,
  is_demo: isDemo,
  no_external: source.no_external === true,
  source_product: 'sevari',
  chain_hash_start: chainHashStart,
  hmac_verified: source.hmac_valid || false,
  received_at: new Date().toISOString(),
  normalise_error: false,
  reject_code: null
}];


// v3.3 IMPROVEMENT: Ingestion fingerprint for replay detection
try {
  const crypto = require('crypto');
  const allItems = $input.all();
  const out = allItems.map(item => {
    const d = item.json;
    const windowMin = Math.floor(Date.now() / 60000);
    const fingerprint_base = (d.channel || '') + '|' + (d.body || '').substring(0, 500) + '|' + windowMin;
    const ingestion_fingerprint = crypto.createHash('sha256').update(fingerprint_base).digest('hex');
    return { json: { ...d, ingestion_fingerprint } };
  });
  return out;
} catch(e) {
  // Fingerprinting is additive — if it fails, pass through unchanged
  return $input.all();
}

if (!$json.enquiry_id) return [{ skip: true }];
return [{ ...$json,
  step_name: 'INTAKE', step_status: 'received',
  detail: 'Enquiry dequeued for processing',
  risk_level: 'low', reversibility: 'reversible',
  approval_required: false, audit_required: true,
  temporal_workflow_name: 'sevari_enquiry_workflow',
  prev_hash: 'GENESIS'
}];

// v3.3 GUARDIAN — behavioural signals + decay model + auto-escalation
const d = $json;
const body = (d.body_decrypted || d.body || '').toLowerCase();
const subject = (d.subject || '').toLowerCase();
const combined = subject + ' ' + body;

// Threat patterns (unchanged detection logic)
const patterns = {
  injection:   /ignore (all )?previous|system prompt|you are now|forget (all )?instructions/i,
  exfiltration: /show me (the )?(api|secret|key|password|token)|dump (the )?database|system prompt/i,
  malicious:   /<script|eval\(|javascript:|onerror=|onclick=/i,
  sensitive_ex: /ssn|social security|credit card number|cvv/i
};

let threat_score = 0;
const reasons = [];

if (patterns.injection.test(combined))    { threat_score += 45; reasons.push('prompt_injection'); }
if (patterns.exfiltration.test(combined)) { threat_score += 50; reasons.push('exfiltration_attempt'); }
if (patterns.malicious.test(combined))    { threat_score += 55; reasons.push('malicious_code'); }
if (patterns.sensitive_ex.test(combined))  { threat_score += 25; reasons.push('sensitive_extraction'); }

// v3.3: Behavioural signals
if (d.burst_flag === true) { threat_score += 30; reasons.push('burst_activity'); }

const repeat_frequency = parseInt(d.sender_frequency || 0);
if (repeat_frequency > 10) { threat_score += 20; reasons.push('high_frequency_sender'); }

// v3.3: Decay model — prior safe history reduces current score
const prior_safe = parseInt(d.prior_safe_count || 0);
const decay_factor = prior_safe >= 10 ? 0.7 : 1.0;
threat_score = Math.round(threat_score * decay_factor);

// v3.3: Auto-escalation
const force_quarantine = threat_score > 75;
const guardian_action = force_quarantine ? 'quarantine' :
                        threat_score > 40 ? 'escalate' :
                        threat_score > 20 ? 'flag' : 'pass';


// v3.4 Consequence loop: repeat high-threat senders go on temp blocklist
const prior_high_threats = parseInt(d.prior_high_threat_count || 0);
const consequence_loop_triggered = threat_score > 80 && prior_high_threats >= 3;
const blocklist_insert = consequence_loop_triggered ? {
  sender_key: d.sender_email_hash || d.ip_address || 'unknown',
  ttl_seconds: 3600,
  reason: 'repeat_high_threat',
  threat_score: threat_score
} : null;

return [{ ...d,
  consequence_loop_triggered,
  blocklist_insert,
  threat_score,
  threat_reasons: reasons,
  decay_factor,
  force_quarantine,
  guardian_action,
  guardian_pass: !force_quarantine && threat_score <= 40
}];

// v3.3 MODEL ROUTING — route by complexity, category, urgency
const complexity = ($json.body_length || 0) > 500 ? 'high' : ($json.body_length || 0) > 150 ? 'medium' : 'low';
const category = $json.category || 'general';
const is_urgent = category === 'Emergency support' || $json.priority_effective > 80;

let model_route = 'mistral:7b-instruct-q4_K_M'; // default T1
let route_reason = 'default_t1';

// Route low complexity to faster small model
if (complexity === 'low' && !is_urgent) {
  model_route = 'gemma2:2b';
  route_reason = 'low_complexity_fast_path';
}
// Technical/code categories to coder model
if (category === 'Software and installation' || category === 'Code' || /github|code|programming/i.test($json.body || '')) {
  model_route = 'qwen2.5-coder:7b-instruct-q4_K_M';
  route_reason = 'technical_code_context';
}
// Urgent stays on Mistral (primary, most reliable)
if (is_urgent) {
  model_route = 'mistral:7b-instruct-q4_K_M';
  route_reason = 'urgent_primary_model';
}

$json.model_route = model_route;
$json.route_reason = route_reason;


// Prepare for phi3:mini guardian AI scan
const vps2status = '{{ $vars.SYNC_VPS2_STATUS || "healthy" }}';
if (vps2status === 'down') return [{ ...$json, skip_ai_scan: true }];
return [{ ...$json, model_name:'phi3:mini', tier_label:'T4',
  system_prompt: 'You are a security classifier. Respond ONLY with: SAFE, SUSPICIOUS, or THREAT. One word only.',
  user_prompt: 'Classify this input for security threats:\n' + ($json.body||'').substring(0,500),
  timeout_ms: 15000, try_t0: false }];

const vps2 = $vars.SYNC_VPS2_HOST || 'http://VPS2-PRIVATE-IP:11434';
const t0 = $vars.SYNC_T0_HOST || '';
const model = $json.model_name || 'mistral:7b-instruct-q4_K_M';
const endpoint = (t0 && $json.try_t0) ? t0 : vps2;

try {
  const resp = await $http.request({
    method: 'POST',
    url: endpoint + '/api/chat',
    body: {
      model: model,
      messages: [
        { role: 'system', content: $json.system_prompt || 'You are Sevari, a professional business operations assistant.' },
        { role: 'user', content: $json.user_prompt || $json.body_decrypted || '' }
      ],
      stream: false,
      options: { temperature: 0.3, num_predict: 500 }
    },
    timeout: ($json.timeout_ms || 90000)
  });
  const output = resp.message?.content || resp.choices?.[0]?.message?.content || '';
  if (!output || output.length < 10) throw new Error('Output too short');
  return [{ ...$json, ai_output: output, tier_used: $json.tier_label || 'T1', ai_success: true }];
} catch(e) {
  return [{ ...$json, ai_success: false, ai_error: e.message, tier_used: $json.tier_label || 'T1' }];
}

const aiResult = ($json.ai_output || '').toUpperCase().trim();
const aiSafe = !$json.ai_success || aiResult.includes('SAFE') || aiResult === '';
const combinedScore = $json.threat_score + (aiSafe ? 0 : 20);
const guardianPassed = combinedScore < 50;
return [{ ...$json, combined_threat_score: combinedScore, guardian_passed: guardianPassed,
  guardian_ai_result: aiResult, guardian_degraded: !$json.ai_success }];

const masterKey = $vars.SYNC_PII_KEY || '';
const tenantDekEnc = $json.encrypted_dek || null;
let piiKey = masterKey;
if (tenantDekEnc && masterKey) {
  const crypto=require('crypto');
  const [iv,tag,enc]=tenantDekEnc.split(':');
  const d=crypto.createDecipheriv('aes-256-gcm',Buffer.from(masterKey,'hex'),Buffer.from(iv,'hex'));
  d.setAuthTag(Buffer.from(tag,'hex'));
  piiKey=Buffer.concat([d.update(Buffer.from(enc,'hex')),d.final()]).toString('hex');
}

// FIX 5: PII encrypted immediately after normalisation, before Guardian
// Guardian receives encrypted fields + body_for_analysis (truncated, no PII identifiers)
const crypto = require('crypto');
const key = $vars.SYNC_PII_KEY || '';

function encrypt(text) {
  if (!text || !key) return text || '';
  try {
    const keyBuf = Buffer.from(key, 'hex');
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-gcm', keyBuf, iv);
    const enc = Buffer.concat([cipher.update(String(text), 'utf8'), cipher.final()]);
    const tag = cipher.getAuthTag();
    return iv.toString('hex') + ':' + tag.toString('hex') + ':' + enc.toString('hex');
  } catch(e) { return '[ENCRYPT_ERROR]'; }
}

// Hash email for thread lookup BEFORE encryption (SHA-256 of normalised email)
// This hash is consistent — same email always produces same hash
const emailNorm = (($json.sender_email || '')).toLowerCase().trim();
const emailHash = emailNorm
  ? crypto.createHash('sha256').update(emailNorm).digest('hex')
  : null;

// Encrypt all PII fields
const encrypted = {
  body_encrypted: encrypt($json.body),
  sender_email_encrypted: encrypt($json.sender_email),
  sender_name_encrypted: encrypt($json.sender_name),
  sender_email_hash: emailHash, // SHA-256 of plaintext — used for thread lookup
  pii_encrypted: true,
  key_version: 1
};

// body_for_analysis: truncated, stripped of obvious PII, for Guardian pattern matching
const bodyForAnalysis = ($json.body || '')
  .replace(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, '[EMAIL]')
  .replace(/\b(?:\+44|0)\s?7\d{3}\s?\d{6}\b/g, '[PHONE]')
  .replace(/\b(?:\d{4}\s){3}\d{4}\b/g, '[CARD]')
  .substring(0, 800);

return [{
  ...$json,
  ...encrypted,
  body: '[ENCRYPTED]',
  sender_email: '[ENCRYPTED]',
  sender_name: '[ENCRYPTED]',
  body_for_analysis: bodyForAnalysis // Guardian uses this, not raw body
}];

const key = $json.api_key || '';
const crypto = require('crypto');
const keyHash = crypto.createHash('sha256').update(key).digest('hex');
return [{ ...$json, api_key_hash: keyHash, api_key: '[CLEARED]' }];

// CRED:TierEnforce — Tier validation + task count lookup
// Sets task_limit and monthly_task_count for ACT:GateCheck enforcement
// Demo mode bypasses limits but still sets values
const tier = $json.tier || 'starter';
const limits = { starter:500, growth:2000, scale:10000, enterprise:-1 };
const taskLimit = limits[tier] || 500;

// monthly_task_count will be populated by CRED:TaskCount DB query
// Set default here — the DB query node sets the real value
return [{
  ...$json,
  task_limit: taskLimit,
  tier_ok: true,
  temporal_workflow_name: 'credentials.tier.enforce',
}];

const crypto = require('crypto');
const intentStr = JSON.stringify({
  subject: $json.subject,
  body: $json.body_encrypted,
  category: $json.category,
  business_id: $json.business_id,
  channel: $json.channel
});
const intentHash = crypto.createHash('sha256').update(intentStr).digest('hex');
return [{ ...$json, intent_hash: intentHash, original_intent_hash: intentHash, trajectory_id: require('crypto').randomUUID() }];

const isExternal = $json.source_system && $json.source_system !== 'sevari';
const hasCIL = $vars.SYNC_CIL_ENABLED === 'true' && isExternal;
return [{ ...$json, is_external: hasCIL, source_system: $json.source_system || 'sevari',
  target_system: $json.target_system || 'internal',
  temporal_workflow_name: 'cil_execution' }];

// Check CIL rate limit
const calls = parseInt($json.calls_made || 0);
const limit = parseInt($json.rate_limit_per_minute || 60);
const costTotal = parseFloat($json.cost_pence_total || 0);
const threshold = parseFloat($vars.SYNC_EXTERNAL_COST_THRESHOLD || 500);
if (calls >= limit || costTotal >= threshold) {
  return [{ ...$json, cil_blocked: true, fallback_to_internal: true }];
}
return [{ ...$json, cil_blocked: false, fallback_to_internal: false }];

// temporal_workflow_name: cil.payload.normalise
// SECURITY: Strip decrypted values before any external call
// These must NEVER reach external integrations
const safe = { ...$json };
delete safe.body_decrypted_for_ai;
delete safe.sender_email_decrypted_for_ai;
$json = safe;


// Normalise external payload to Sevari schema
const action_id = require('crypto').randomUUID();
return [{ ...$json,
  action_id, audit_required: true,
  risk_level: $json.risk_level || 'low',
  reversibility: $json.reversibility || 'reversible',
  reversal_possible: $json.reversibility !== 'irreversible',
  payload_hash: require('crypto').createHash('sha256').update(JSON.stringify($json)).digest('hex')
}];

const body = ($json.body_encrypted || $json.body || '').toLowerCase();
const subj = ($json.subject || '').toLowerCase();
const combined = subj + ' ' + body;
let matchedCategory = 'General enquiry';
let matchedKeywords = [];
let maxScore = 0;
const categories = $json.categories || [];
for (const cat of categories) {
  const kws = Array.isArray(cat.keywords) ? cat.keywords : JSON.parse(cat.keywords || '[]');
  let score = kws.filter(k => combined.includes(k.toLowerCase())).length;
  if (score > maxScore) { maxScore = score; matchedCategory = cat.category_name; matchedKeywords = kws.filter(k=>combined.includes(k.toLowerCase())); }
}
return [{ ...$json, category: matchedCategory, matched_keywords: matchedKeywords, classification_score: maxScore, sla_hours: 4 }];

// FIXED ISSUE 8: RAG pipeline with re-ranking, relevance filtering, token control
const results = Array.isArray($json) ? $json : [$json];

// 1. Relevance threshold — discard low-similarity results
const RELEVANCE_THRESHOLD = 0.35;
const relevant = results.filter(r => parseFloat(r.similarity || 0) >= RELEVANCE_THRESHOLD);

// 2. Re-rank by weighted authority score
// authority_weight * similarity gives a combined score
const reranked = relevant
  .map(r => ({
    ...r,
    combined_score: (parseFloat(r.similarity || 0) * 0.7) + (parseFloat(r.authority_weight || 0.4) * 0.3)
  }))
  .sort((a, b) => b.combined_score - a.combined_score)
  .slice(0, 3); // Top 3 after re-ranking

// 3. Token budget control — truncate content to fit within context window
const MAX_CONTEXT_TOKENS = 800; // ~600 words
let tokenBudget = MAX_CONTEXT_TOKENS;
const snippets = [];
for (const r of reranked) {
  const content = (r.content_encrypted || r.title || '').substring(0, 400);
  const estimatedTokens = Math.ceil(content.length / 4);
  if (tokenBudget - estimatedTokens < 0) break;
  snippets.push({
    title: r.title,
    content,
    similarity: r.similarity,
    authority_weight: r.authority_weight,
    source_system: r.source_system || 'manual',
    source_visibility: r.source_visibility || 'sovereign'
  });
  tokenBudget -= estimatedTokens;
}

// 4. Relevance validation — flag if no relevant results found
const hasContext = snippets.length > 0;
const avgSimilarity = snippets.reduce((a, s) => a + parseFloat(s.similarity || 0), 0) / (snippets.length || 1);

const contextText = snippets.map(s => s.title + ': ' + s.content).join('\n\n');

// IMPROVEMENT 4: Set rag_mode flag based on result quality
const ragMode = (relevant.length === 0) ? 'degraded' : 
                (relevant.length < 2) ? 'limited' : 'active';
const kbHasContext = relevant.length > 0;


// v3.3 IMPROVEMENT: Source traceability per snippet
if (Array.isArray(results)) {
  results = results.map(r => ({
    ...r,
    source_id: r.kb_id || r.source_id || 'unknown',
    last_updated: r.updated_at || r.last_updated || null,
    trust_level: r.authority_weight >= 0.8 ? 'high' : r.authority_weight >= 0.5 ? 'medium' : 'low'
  }));
}
return [{
  ...$json,
  kb_context: contextText,
  kb_snippets_used: snippets,
  kb_relevance_score: avgSimilarity,
  kb_has_context: hasContext,
  kb_results_count: snippets.length,
  confidence_raw: hasContext ? 0.7 : 0.45 // lower confidence if no KB context
}];

const vps2Down = '{{ $vars.SYNC_VPS2_STATUS || "healthy" }}' === 'down';
const systemPrompt = 'You are responding on behalf of ' + ($json.business_name || 'the business') +
  '. Industry: ' + ($json.industry || 'general') + '. Customer type: ' + ($json.customer_type || 'individual') +
  '. Communication style: ' + ($json.communication_style || 'standard') + '.\n\n' +
  'Knowledge base context:\n' + ($json.kb_context || 'No specific context available.') + '\n\n' +
  'Category: ' + ($json.category || 'General enquiry') + '. SLA: ' + ($json.sla_hours || 4) + ' hours.\n\n' +
  'Write a professional, helpful reply. Do not mention Sevari, Veylith Systems, or AI.';
const userPrompt = 'Enquiry subject: ' + ($json.subject || '') + '\n\nMessage: ' + ($json.body_decrypted_for_ai || $json.body || '');
return [{ ...$json, system_prompt: systemPrompt, user_prompt: userPrompt, skip_ai: vps2Down,
  step_name: 'HIVE', step_status: 'complete', detail: 'Context built, routing to AI chain' }];

// v3.3 IMPROVEMENT: CE loop prevention (max 2 clarifications, then fall back)
if ($json.skip_ce === true) return [{ ...$json, needs_clarification: false }];

const clarification_count = parseInt($json.clarification_count || 0);
if (clarification_count >= 2) {
  // Already asked twice — fall back to best-effort response, do not ask again
  return [{ ...$json,
    needs_clarification: false,
    clarification_exhausted: true,
    force_best_effort: true
  }];
}


// Skip CE if this is a clarification follow-up being reprocessed
if ($json.skip_ce === true) return [{ ...$json, needs_clarification: false }];


// FIXED ISSUE 9: Improved CE with multi-signal ambiguity detection
const body = ($json.body_decrypted || $json.body_decrypted_for_ai || $json.body_decrypted_for_ai || $json.body || '').trim();
const subject = ($json.subject || '').trim();
const confidence = $json.confidence_raw || 0.7;
const category = $json.category || 'General enquiry';
const hasKeywords = $json.matched_keywords && $json.matched_keywords.length > 0;
const isDemo = $json.is_demo || false;

// Never clarify in demo mode
if (isDemo) return [{ ...$json, needs_clarification: false }];

// Word count
const wordCount = body.split(/\s+/).filter(Boolean).length;
const subjectWordCount = subject.split(/\s+/).filter(Boolean).length;

// Ambiguity signals — multiple triggers, each weighted
let ambiguityScore = 0;

// Signal 1: Very low confidence despite processing
if (confidence < 0.35) ambiguityScore += 30;
else if (confidence < 0.45) ambiguityScore += 15;

// Signal 2: Very short body (but not if subject is clear)
if (wordCount < 8 && subjectWordCount < 3) ambiguityScore += 25;
else if (wordCount < 15 && !hasKeywords) ambiguityScore += 10;

// Signal 3: No matched keywords in classification
if (!hasKeywords) ambiguityScore += 20;

// Signal 4: Body contains only questions without context
const onlyQuestions = /^[^.!]+\?\s*$/.test(body) && wordCount < 12;
if (onlyQuestions) ambiguityScore += 20;

// Signal 5: Generic category with no supporting signals
if (category === 'General enquiry' && !hasKeywords && wordCount < 30) ambiguityScore += 15;

// Signal 6: Long message but still unclear (contradictory signals)
if (wordCount > 50 && confidence < 0.4 && !hasKeywords) ambiguityScore += 10;

// Signal 7: Multiple possible interpretations
const ambiguousPhrases = ['not sure', 'don\'t know', 'maybe', 'or maybe', 'something like', 'kind of', 'sort of'];
if (ambiguousPhrases.some(p => body.toLowerCase().includes(p))) ambiguityScore += 15;

// Threshold for triggering clarification
const needsClarification = ambiguityScore >= 40;

if (!needsClarification) return [{ ...$json, needs_clarification: false, ambiguity_score: ambiguityScore }];

// Generate a targeted, helpful clarifying question
// Never say "I don't understand" — always sound like a helpful person
const questions = {
  'Emergency support': 'To make sure I get the right person to you — could you tell me a bit more about what has stopped working?',
  'Remote support request': 'Happy to help. Could you tell me what the issue is with the device — so I can get the right person to assist?',
  'Device or hardware fault': 'Thanks for getting in touch. Could you tell me a bit more about what the device is doing — or not doing?',
  'Network and connectivity': 'To point you in the right direction — is the issue with your internet, your network, or a specific device?',
  'Software and installation': 'Could you tell me a bit more — is this about installing something new, or an existing program that is not working?',
  'New client enquiry': 'Great to hear from you. Could you tell me a bit more about what you are looking for — so I can make sure we are the right fit?',
  'Quote request': 'To make sure I give you an accurate quote — could you tell me a bit more about what you need and when you need it?',
  'General enquiry': 'Thanks for getting in touch. To make sure I respond with the right information — could you tell me a little more about what you need help with?'
};

const question = questions[category] || questions['General enquiry'];

return [{
  ...$json,
  needs_clarification: true,
  ambiguity_score: ambiguityScore,
  clarification_question: question,
  awaiting_clarification: true
}];

// STYLE MIRRORING: Sevari mirrors the user's communication style,
// but NEVER inherits the user's risk. Risk level is determined by
// the system (drift score, category, content) — not by how the
// sender writes.
const commStyle = $json.communication_style || 'standard';
const industry  = $json.industry || 'general';
const userTone  = $json.detected_tone || 'neutral';

// Style matrix — mirrors surface tone, holds firm on risk
const styleGuide = {
  concise:  'Reply concisely and directly. Match the brevity of professional correspondence. No padding.',
  standard: 'Reply professionally and warmly. Balanced tone. Clear and accessible.',
  formal:   'Reply formally. Full sentences. Precise language. Professional register throughout.'
};

const styleInstruction = styleGuide[commStyle] || styleGuide.standard;

// Tone adaptation — mirrors STYLE not RISK
// If sender is urgent/anxious: match pace, not panic
// If sender is casual: warm but professional
