const vps2 = $vars.SYNC_VPS2_HOST || 'http://VPS2-PRIVATE-IP:11434';
const t0 = $vars.SYNC_T0_HOST || '';
const model = $json.model_name || 'mistral:7b-instruct-q4_K_M';
const endpoint = (t0 && $json.try_t0) ? t0 : vps2;

try {
  const resp = await $http.request({
    method: 'POST',
    url: endpoint + '/api/chat',
    body: {
      model: model,
      messages: [
        { role: 'system', content: $json.system_prompt || 'You are Sevari, a professional business operations assistant.' },
        { role: 'user', content: $json.user_prompt || $json.body_decrypted_for_ai || '' }
      ],
      stream: false,
      options: { temperature: 0.3, num_predict: 500 }
    },
    timeout: ($json.timeout_ms || 90000)
  });
  const output = resp.message?.content || resp.choices?.[0]?.message?.content || '';
  if (!output || output.length < 10) throw new Error('Output too short');
  return [{ ...$json, ai_output: output, tier_used: $json.tier_label || 'T1', ai_success: true }];
} catch(e) {
  return [{ ...$json, ai_success: false, ai_error: e.message, tier_used: $json.tier_label || 'T1' }];
}

// ── MIGRATION TAGS ──────────────────────────────────────────────────
// Temporal: temporal_workflow_name set in prep node
// vLLM: Change SYNC_VPS2_HOST to vLLM OpenAI-compatible endpoint
//        e.g. http://vps2:8000/v1 — no code changes required
// GPU RTX 4060 Ti (current): mistral:7b-instruct-q4_K_M via SYNC_T0_HOST
// GPU RTX 4090 (upgrade): mixtral:8x7b or llama3.1:8b via SYNC_T0_HOST  
// GPU RTX 6000 Ada (Temporal phase): 70B models via vLLM SYNC_VPS2_HOST
// PgBouncer: all DB connections via port 6432 (set in credentials)
// ────────────────────────────────────────────────────────────────────

const vps2 = $vars.SYNC_VPS2_HOST || 'http://VPS2-PRIVATE-IP:11434';
const t0 = $vars.SYNC_T0_HOST || '';
const model = $json.model_name || 'llama3.2:3b';
const endpoint = (t0 && $json.try_t0) ? t0 : vps2;

try {
  const resp = await $http.request({
    method: 'POST',
    url: endpoint + '/api/chat',
    body: {
      model: model,
      messages: [
        { role: 'system', content: $json.system_prompt || 'You are Sevari, a professional business operations assistant.' },
        { role: 'user', content: $json.user_prompt || $json.body_decrypted_for_ai || '' }
      ],
      stream: false,
      options: { temperature: 0.3, num_predict: 500 }
    },
    timeout: ($json.timeout_ms || 90000)
  });
  const output = resp.message?.content || resp.choices?.[0]?.message?.content || '';
  if (!output || output.length < 10) throw new Error('Output too short');
  return [{ ...$json, ai_output: output, tier_used: $json.tier_label || 'T1', ai_success: true }];
} catch(e) {
  return [{ ...$json, ai_success: false, ai_error: e.message, tier_used: $json.tier_label || 'T1' }];
}

// Agent template fallback - per agent per task type
const templates = {
  HERALD: 'Content draft for {business_name}: [Content for {industry} audience - requires completion]',
  SENTINEL: 'System health check completed. All primary systems operational. Queue depth nominal.',
  default: 'Task received and logged. Reference: ' + $json.enquiry_id
};
const template = templates[$json.active_agent] || templates.default;
return [{ ...$json, ai_output: template, tier_used:'T5-AGENT', template_used:true }];

// FEATURE GATING BY TIER
const featureGate={starter:['reply','send_email','send_sms'],
  growth:['reply','send_email','send_sms','crm_create','crm_update','log_activity'],
  scale:['reply','send_email','send_sms','crm_create','crm_update','log_activity',
    'booking_create','availability_check','create_event','payment_create','payment_request'],
  enterprise:['*']};
const allowed=featureGate[tier]||featureGate.starter;
if(!allowed.includes('*')&&!allowed.includes(actionType)&&!isDemoMode)
  return[{...$json,final_gate:'block',gate_reason:'feature_not_on_tier',
    gate_detail:actionType+' not on '+tier+'. Upgrade required.',blocked:true,downgrade_to:'reply'}];

// ACT:GateCheck — Action Gate with full enforcement
// Enforces: connector availability | tier permissions | task limits | approval requirements
// Hard rule: if required_connector not configured → BLOCK. No guessing. No fallback execution.
// temporal_workflow_name: action.gate.check

const gateLevel     = $json.gate_level || 'auto';
const operatingMode = $json.operating_mode || 'assist';
const riskLevel     = $json.risk_level || 'low';
const isFinancial   = $json.active_agent === 'LEDGER' || $json.action_type === 'payment_request';
const isIrreversible= $json.reversibility === 'irreversible';
const isDemoMode    = $json.is_demo || $json.no_external;
const tier          = $json.tier || 'starter';
const actionType    = $json.action_type || 'reply';

// ── TIER AGENT ENFORCEMENT ─────────────────────────────────────────
// Hard rule: agents only available at correct tier
const tierAgentMap = {
  starter:    ['BASTION','SENTINEL'],
  growth:     ['BASTION','SENTINEL','HERALD','VANGUARD'],
  scale:      ['BASTION','SENTINEL','HERALD','VANGUARD','COMPASS','LEDGER'],
  enterprise: ['BASTION','SENTINEL','HERALD','VANGUARD','COMPASS','LEDGER','FORGE'],
};
const allowedAgents = tierAgentMap[tier] || tierAgentMap.starter;
const activeAgent   = $json.active_agent || 'BASTION';

if (!allowedAgents.includes(activeAgent) && !isDemoMode) {
  return [{ ...$json,
    final_gate: 'block',
    gate_reason: 'agent_not_on_tier',
    gate_detail: activeAgent + ' requires tier upgrade. Current tier: ' + tier,
    approval_required: false,
    blocked: true,
  }];
}

// ── TASK LIMIT ENFORCEMENT ─────────────────────────────────────────
const taskLimits = { starter: 500, growth: 2000, scale: 10000, enterprise: -1 };
const taskLimit  = taskLimits[tier] || 500;
const taskCount  = parseInt($json.monthly_task_count || 0);
if (taskLimit !== -1 && taskCount >= taskLimit && !isDemoMode) {
  return [{ ...$json,
    final_gate: 'block',
    gate_reason: 'task_limit_reached',
    gate_detail: 'Monthly limit ' + taskLimit + ' reached (' + taskCount + '/' + taskLimit + '). Upgrade to continue.',
    blocked: true,
  }];
}

// ── CONNECTOR AVAILABILITY ENFORCEMENT ────────────────────────────
// Hard rule from brief: if required_connector not configured → block
// No execution without confirmed connector. No guessing.
const registry        = $json.connector_registry || {};
const actionConnMap   = $json.action_connector_map || {};
const requiredCategory= actionConnMap[actionType] || null;

if (requiredCategory && requiredCategory !== 'webhook' && !isDemoMode) {
  const connector = registry[requiredCategory] || {};
  if (!connector.has_credentials || connector.status !== 'active') {
    return [{ ...$json,
      final_gate: 'block',
      gate_reason: 'connector_not_configured',
      gate_detail: 'Action "' + actionType + '" requires a ' + requiredCategory + ' connector. Configure in Settings → Integrations.',
      required_connector: requiredCategory,
      connector_status: connector.status || 'unconfigured',
      blocked: true,
    }];
  }
}

// ── APPROVAL RULES (existing logic preserved) ─────────────────────
if (isFinancial)   return [{ ...$json, final_gate:'require', gate_reason:'financial_action', approval_required:true }];
if (isIrreversible)return [{ ...$json, final_gate:'require', gate_reason:'irreversible_action', approval_required:true }];
if ($json.drift_score > 40) return [{ ...$json, final_gate:'require', gate_reason:'high_drift', approval_required:true }];
if ($json.confidence_adjusted < 0.5) return [{ ...$json, final_gate:'require', gate_reason:'low_confidence', approval_required:true }];
if (isDemoMode)    return [{ ...$json, final_gate:'auto', gate_reason:'demo_mode', approval_required:true }];
if (operatingMode === 'assist') return [{ ...$json, final_gate:'require', gate_reason:'assist_mode', approval_required:true }];
if (operatingMode === 'copilot') {
  const requireApproval = riskLevel === 'high' || isFinancial;
  return [{ ...$json, final_gate: requireApproval ? 'require':'auto', gate_reason:'copilot_mode', approval_required: requireApproval }];
}
return [{ ...$json, final_gate:'auto', gate_reason:'auto_approved', approval_required:false }];

const domain = $vars.SYNC_DOMAIN || 'https://veylith.systems';
const token = $json.approval_token || '';
const preview = ($json.action_preview || '').substring(0, 120);
const msg = 'Sevari by Veylith Systems:\n' +
  $json.action_type + ' — ' + ($json.agent_name || '') + '\n\n' +
  preview + '\n\n' +
  'Reply APPROVE ' + $json.enquiry_id + ' or REJECT ' + $json.enquiry_id + '\n' +
  'Or tap: ' + domain + '/webhook/sync/approve?t=' + token;
return [{ ...$json, sms_message: msg }];

// Check if SMS delivered after 60s - in n8n this would be a wait + check
// For now we log for monitoring and proceed
return [{ ...$json, sms_fallback_checked: true }];

const body = ($json.Body || '').trim().toUpperCase();
const parts = body.split(/\s+/);
const action = parts[0]; // APPROVE or REJECT
const ref = parts[1] || '';
return [{ ...$json, sms_action: action, sms_ref: ref, sender_mobile: $json.From }];

const token = $json.t || $json.query?.t || '';
const preview = $json.action_preview || 'Action pending approval';
const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Sevari — Approve Action</title>
<style>body{font-family:system-ui;background:#09101C;color:#fff;margin:0;display:flex;align-items:center;justify-content:center;min-height:100vh;padding:24px}
.box{background:#111927;border:1px solid rgba(255,255,255,0.08);border-radius:8px;padding:32px;max-width:400px;width:100%;text-align:center}
.logo{font-size:24px;font-weight:800;color:#0EA5A5;margin-bottom:4px}
.sub{font-size:12px;color:#7A8EA0;margin-bottom:24px}
.preview{background:#192130;padding:14px;border-radius:4px;font-size:13px;color:#BFD0DF;text-align:left;margin-bottom:24px;border-left:2px solid #0EA5A5}
.btn{display:block;width:100%;padding:14px;border-radius:4px;font-size:14px;font-weight:700;cursor:pointer;border:none;margin-bottom:10px;transition:all .2s}
.approve{background:#0EA5A5;color:#09101C}
.reject{background:transparent;color:#7A8EA0;border:1px solid #3A5060}
.ref{font-size:10px;color:#3A5060;margin-top:16px}
</style></head>
<body><div class="box">
<div class="logo">SEVARI</div><div class="sub">by Veylith Systems</div>
<div class="preview">${preview}</div>
<button class="btn approve" onclick="respond('approve')">✓ Approve</button>
<button class="btn reject" onclick="respond('reject')">✕ Reject</button>
<div class="ref">Token: ${token.substring(0,8)}...</div>
</div>
<script>async function respond(action){const r=await fetch('/webhook/sync/approve/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:'${token}',action})});if(r.ok)document.body.innerHTML='<div style="text-align:center;padding:48px;font-family:system-ui"><div style="color:#0EA5A5;font-size:48px">'+action.charAt(0).toUpperCase()+'</div><div style="color:#fff;margin-top:16px">'+action+'d</div></div>';}</script>
</body></html>`;
return [{ ...$json, html_response: html }];

// ECO:Registry — Tenant Connector Registry
// Loads all configured connectors for this tenant
// Returns structured connector map: {category: {provider, status, has_credentials}}
// Hard rule: if required_connector not configured → block execution (never guess)
// temporal_workflow_name: eco.registry.load

const bizId = $json.business_id;

// Default connector map — all unconfigured
const connectorMap = {
  email:    { provider: null, status: 'unconfigured', has_credentials: false },
  sms:      { provider: null, status: 'unconfigured', has_credentials: false },
  crm:      { provider: null, status: 'unconfigured', has_credentials: false },
  calendar: { provider: null, status: 'unconfigured', has_credentials: false },
  booking:  { provider: null, status: 'unconfigured', has_credentials: false },
  payments: { provider: null, status: 'unconfigured', has_credentials: false },
  storage:  { provider: null, status: 'unconfigured', has_credentials: false },
  webhook:  { provider: 'universal', status: 'available', has_credentials: true },
};

// Override with Sevari native connectors (always available — VPS1 SMTP + Twilio)
// These are the platform defaults before tenant adds their own
if ($vars.SYNC_FROM_EMAIL) {
  connectorMap.email = { provider: 'smtp_native', status: 'active', has_credentials: true };
}
if ($vars.SYNC_TWILIO_FROM) {
  connectorMap.sms = { provider: 'twilio_native', status: 'active', has_credentials: true };
}
// Stripe (native — provisioned at signup)
connectorMap.payments = { provider: 'stripe_native', status: 'active', has_credentials: true };

// Action→connector resolution map
// Used by ACT:GateCheck to verify connector before allowing execution
const actionConnectorMap = {
  'reply':              'email',
  'reply_sms':          'sms',
  'send_email':         'email',
  'send_sms':           'sms',
  'crm_write':          'crm',
  'crm_update':         'crm',
  'log_activity':       'crm',
  'booking_create':     'booking',
  'booking_confirm':    'booking',
  'availability_check': 'calendar',
  'create_event':       'calendar',
  'payment_request':    'payments',
  'payment_confirm':    'payments',
  'document_store':     'storage',
  'document_retrieve':  'storage',
  'webhook':            'webhook',
};

return [{
  ...$json,
  connector_registry:      connectorMap,
  action_connector_map:    actionConnectorMap,
  connectors_loaded:       true,
  registry_loaded_at:      new Date().toISOString(),
}];

// Time-decay adjusted score calculation for HIVE patterns
// Used in hive_patterns queries: score * EXP(-EXTRACT(EPOCH FROM (NOW() - recorded_at)) / 86400)
const pattern = {
  business_id: $json.business_id,
  pattern_type: $json.is_task ? 'agent_execution' : 'enquiry_classification',
  category: $json.category,
  agent_name: $json.target_agent,
  tier_used: $json.tier_used,
  success: $json.ai_success || $json.template_used || false,
  approval_outcome: $json.approval_outcome || 'auto',
  duration_ms: $json.duration_ms || 0,
  confidence_score: $json.confidence_adjusted || 0.7,
  drift_score: $json.drift_score || 0,
  trajectory_id: $json.trajectory_id
};
return [{ ...$json, hive_pattern: pattern }];

const crypto = require('crypto');
const prevHash = $json.prev_hash || 'GENESIS';
const rowContent = JSON.stringify({
  enquiry_id: $json.enquiry_id, business_id: $json.business_id,
  step_name: $json.step_name, step_status: $json.step_status,
  detail: $json.detail, timestamp: new Date().toISOString(),
  prev_hash: prevHash
});
const rowHash = crypto.createHash('sha256').update(rowContent).digest('hex');
return [{ ...$json, prev_hash: prevHash, row_hash: rowHash }];

if (!$json.is_demo && !$json.no_external) return [$json];
return [{ ...$json, demo_response: {
  enquiry_id: $json.enquiry_id, response: $json.final_output,
  category: $json.category, tier_used: $json.tier_used,
  confidence: $json.confidence_adjusted, trajectory_id: $json.trajectory_id,
  audit_chain: $json.row_hash
}}];

// OUT:Final — Final response delivery gate
// Handles both API/webhook responses and queued approval responses
// This node is the last step before the enquiry is considered complete

const isDemo = $json.is_demo || $json.no_external;
const approvalRequired = $json.approval_required;
const channel = $json.channel || 'api';
const finalOutput = $json.final_output || $json.ai_output || $json.template_output || '';
const enquiryId = $json.enquiry_id;
const bizId = $json.business_id;

// Build the canonical outbound record
const outbound = {
  enquiry_id:   enquiryId,
  business_id:  bizId,
  channel:      channel,
  response:     finalOutput,
  tier_used:    $json.tier_used || 'T1',
  confidence:   $json.confidence_adjusted || 0,
  is_demo:      isDemo,
  sent_at:      new Date().toISOString(),
  approval_required: approvalRequired,
  trajectory_id: $json.trajectory_id || null,
  audit_hash:   $json.row_hash || null,
  operating_mode: $json.operating_mode || 'assist',
};

// Demo: return result directly, no external action
if (isDemo) {
  return [{ ...outbound, delivery_status: 'demo_complete', external_sent: false }];
}

// Approval required: pipeline ends here — SMS node handles delivery after approval
if (approvalRequired) {
  return [{ ...outbound, delivery_status: 'queued_for_approval', external_sent: false }];
}

// Auto-send path: mark as ready for external delivery
// Actual email/webhook send is handled by downstream channel-specific nodes
return [{ ...outbound, delivery_status: 'ready_to_send', external_sent: true }];

// OP:InitLogic — system initialisation check
const domain = $vars.SYNC_DOMAIN || 'https://veylith.systems';
const phase  = parseInt($vars.SYNC_PHASE || '1');
return [{ json: { status:'ok', domain, phase, init_at: new Date().toISOString() } }];

// Set demo flags and route to main pipeline
return [{ ...$json, is_demo:true, no_external:true, demo_mode:'pipeline_only',
  business_id: $json.business_id || 'BIZ-DEMO-001',
  channel: 'widget',
  step_name: 'DEMO_INTAKE', step_status: 'received',
  detail: 'Demo pipeline execution - no external actions' }];

