const event = $json;
const eventType = event.type;
if (eventType === 'checkout.session.completed') {
  const meta = event.data?.object?.metadata || {};
  return [{ ...$json, stripe_action: 'provision', tier: meta.tier || 'starter',
    customer_email: event.data?.object?.customer_email,
    stripe_customer_id: event.data?.object?.customer,
    stripe_subscription_id: event.data?.object?.subscription }];
}
if (eventType === 'customer.subscription.deleted') return [{ ...$json, stripe_action: 'cancel' }];
return [{ ...$json, stripe_action: 'log_only' }];

// v3.4.4 ADMIN:AuthCheck — fixed broken syntax
const adminKey = $json.headers?.['x-admin-key'] || $json.query?.k || '';
const crypto = require('crypto');

if (!adminKey) {
  return [{ json: { ...$json, admin_auth_failed: true, reason: 'no_key', http_status: 401 }}];
}

const keyHash = crypto.createHash('sha256').update(adminKey).digest('hex');
const expectedHash = $vars.SYNC_ADMIN_KEY_HASH || '';

if (!expectedHash) {
  return [{ json: { ...$json, admin_auth_failed: true, reason: 'env_not_configured', http_status: 503 }}];
}

if (keyHash !== expectedHash) {
  return [{ json: { ...$json, admin_auth_failed: true, reason: 'invalid_key', http_status: 401 }}];
}

// Auth passed — log admin session
const sessionId = 'ADMIN-' + Date.now().toString(36).toUpperCase();
return [{ json: { ...$json, admin_auth_failed: false, session_id: sessionId }}];

// Generate recommendations based on patterns
const patterns = Array.isArray($json) ? $json : [$json];
const recs = [];
for (const p of patterns) {
  if (p.adjusted_score < 0.4 && p.count > 5) {
    recs.push({ business_id: p.business_id, rec_type: 'routing_change',
      recommendation_json: JSON.stringify({ category: p.category, suggestion: 'Review classification keywords' }),
      justification: 'Low confidence score over ' + p.count + ' occurrences', status: 'pending', approver_role: 'admin' });
  }
}
return recs.length ? recs.map(r=>({...r})) : [{ no_recs: true }];

const records = Array.isArray($json) ? $json : [$json];
let chainValid = true;
for (let i = 1; i < records.length; i++) {
  if (records[i-1].prev_hash !== records[i].row_hash) { chainValid = false; break; }
}

// Write gaps to audit_gap_log
const gaps = [];
for (let i = 1; i < records.length; i++) {
  if (records[i-1].prev_hash !== records[i].row_hash) {
    gaps.push({ expected: records[i].prev_hash, actual: records[i-1].row_hash, position: i });
  }
}
return [{ chain_valid: chainValid, records_checked: records.length,
  checked_at: new Date().toISOString(), gaps_found: gaps.length, gaps }];

// Per-tenant brief builder — respects their channel preference and time choice
const b = $json;
if (!b.brief_enabled) return []; // Not enabled for this tenant

const domain = $vars.SYNC_DOMAIN || 'https://veylith.systems';
const subject = 'Sevari — your operation summary · ' + new Date().toLocaleDateString('en-GB', {weekday:'long',day:'numeric',month:'long'});

const bodyText = [
  'Hi' + (b.business_name ? ' — ' + b.business_name : '') + ',',
  '',
  'Here is what Sevari handled since your last briefing.',
  '',
  '📥 Messages received: ' + (b.overnight_enquiries || 0),
  '✅ Awaiting your approval: ' + (b.approvals_pending || 0),
  '',
  b.approvals_pending > 0 ? 'You have messages waiting. Tap to review: ' + domain : 'Everything is handled. Nothing is waiting for you.',
  '',
  'Sevari by Veylith Systems'
].join('\n');

const results = [];

// Email channel
if (b.brief_channel === 'email' || b.brief_channel === 'both') {
  results.push({
    ...b,
    to_address: b.owner_email,
    subject,
    body_html: bodyText.replace(/\n/g,'<br>'),
    email_type: 'brief',
    send_via: 'email'
  });
}

// SMS channel  
if (b.brief_channel === 'sms' || b.brief_channel === 'both') {
  const smsText = 'Sevari: ' + (b.overnight_enquiries||0) + ' messages handled. ' +
    (b.approvals_pending > 0 ? b.approvals_pending + ' waiting for you.' : 'Nothing waiting.');
  results.push({
    ...b,
    sms_message: smsText,
    send_via: 'sms'
  });
}

return results;

const b = $json;
return [{ to_address: b.owner_email, subject: 'Sevari Evening Summary — ' + new Date().toLocaleDateString('en-GB'),
  body_html: '<p>Good evening,</p><p>Today Sevari handled <strong>' + (b.completed_today||0) + '</strong> enquiries for ' + (b.business_name||'your operation') + '.</p><p>Sevari by Veylith Systems</p>',
  email_type: 'brief' }];

const capture_outcome = {type:"successful_resolution",is_anonymised:true,capture_at:new Date().toISOString()};
// OWNER SELF-MARKETING PIPELINE — internal only
// This node runs for Veylith Systems, not for tenants
// Never expose this to tenant dashboard. Owner approval always required.
// Flags: owner_self_marketing=true, requires_owner_approval=true

const phaseResult = await $http.request({ method:'GET', url: ($vars.SYNC_DOMAIN||'https://veylith.systems') + '/webhook/sync/phase' });
const phase = parseInt(phaseResult.phase) || 1;
// Phase 1: build brand awareness - no product mentions
// Phase 2+: product-aware content
const contentTypes = ['problem_post','education_post','proof_post','milestone_post'];
const today = new Date().getDay();
const contentType = contentTypes[today % contentTypes.length];
return [{ ...$json, content_type: contentType, phase, temporal_workflow_name: 'sevari_herald_workflow' }];

