// The invariant layer — protects Sevari's identity from drift
const rec = $json;
if (rec.no_recs) return [$json]; // no recommendations to check

const VIOLATIONS = [
  { pattern: /disable|bypass|skip|remove|optional/i, constants: ['AUDIT_TRAIL_IMMUTABILITY','GUARDIAN_INDEPENDENCE','FAILSAFE_FLOOR'], check: true },
  { pattern: /cloud|openai|anthropic|google|external.?ai|third.?party.?ai/i, constants: ['DATA_SOVEREIGNTY'], check: true },
  { pattern: /approval|financial|financial.?auto|auto.?approve.?financial/i, constants: ['HUMAN_APPROVAL_FLOOR'], check: true },
  { pattern: /cross.?tenant|other.?tenant|tenant.?data|share.?between/i, constants: ['TENANT_ISOLATION_ABSOLUTE'], check: true },
];

const recStr = JSON.stringify(rec).toLowerCase();
const violations = [];

for (const v of VIOLATIONS) {
  if (v.pattern.test(recStr)) {
    violations.push({ constants: v.constants, matched: recStr.match(v.pattern)?.[0] });
  }
}

// Check for identity drift — recommendations that change purpose
const purposeShift = /replace|automate.?human|remove.?human|autonomous.?without/i.test(recStr);
if (purposeShift) violations.push({ constants: ['PURPOSE','NO_IDENTITY_DRIFT'], matched: 'purpose_shift' });

if (violations.length > 0) {
  return [{ ...$json, constitution_violation: true, violations, auto_rejected: true,
    rejection_reason: 'Constitutional violation — recommendation conflicts with invariant: ' + violations.map(v=>v.constants.join(',')).join('; ') }];
}

return [{ ...$json, constitution_violation: false, constitution_cleared: true }];

const bizName = $json.business_name || '';
const ch = $json.companies_house || {};
const gp = $json.google_places || {};
const osm = $json.osm || {};
const wiki = $json.wiki || {};
const prompt = 'Summarise the following data about "' + bizName + '" into a 3-4 sentence business profile for use in an AI knowledge base. Focus on: what they do, where they operate, and any notable characteristics.\n\nData: ' +
  JSON.stringify({ companies_house: ch, google_places: gp, location: osm, industry_context: wiki?.extract?.substring(0,300) });
return [{ ...$json, model_name:'phi3:mini', tier_label:'EKP', timeout_ms:20000,
  system_prompt: 'You are a business analyst. Produce concise, factual business profiles. Maximum 4 sentences.',
  user_prompt: prompt }];

// Weight every knowledge source used in this context
const kbSnippets = $json.kb_snippets_used || [];
const sourceWeights = {
  'internal_enterprise': 1.0,
  'premium_paid': 0.8,
  'public_web': 0.4,
  'proprietary_silo': 0.9,
  'deep_mesh': 0.6,
  'manual': 0.7,
  'ekp_sourced': 0.45,
  'default': 0.4
};
const citations = kbSnippets.map(s => ({
  source_system: s.source_system || 'manual',
  authority_weight: sourceWeights[s.source_category || 'default'] || 0.4,
  evidence_summary: (s.title || s).substring(0, 100)
}));
const avgAuthority = citations.length
  ? citations.reduce((a,c) => a + c.authority_weight, 0) / citations.length
  : 0.4;
return [{ ...$json, authority_citations: citations, avg_authority_weight: avgAuthority,
  confidence_raw: Math.min(1.0, ($json.confidence_raw || 0.7) * (0.5 + avgAuthority * 0.5)) }];

const records = Array.isArray($json) ? $json : [$json];
const stale = records.filter(r => r.freshness === 'stale');
return stale.length ? stale.map(r => ({
  ...r, flag_stale: true, action_taken: 'queued_refresh',
  check_type: 'staleness'
})) : [{ no_stale_records: true }];

const actionType = $json.action_type || '';
if (actionType !== 'knowledge_ingest') return [$json];
// Route to appropriate knowledge connector based on source
const source = $json.knowledge_source || 'public_web';
const routes = {
  'internal_enterprise': { connector: 'INT:KB:EnterpriseConnector', auth: 'oauth2' },
  'premium_paid': { connector: 'INT:KB:PremiumConnector', auth: 'apikey' },
  'public_web': { connector: 'EKP:CompaniesHouse', auth: 'none' },
  'proprietary_silo': { connector: 'INT:KB:SiloConnector', auth: 'oauth2' },
  'deep_mesh': { connector: 'INT:KB:DeepMeshConnector', auth: 'hmac' }
};
