let stressLevel = 'normal';
if (queueDepth > 100 || dlqDepth > 10) stressLevel = 'high';
if (queueDepth > 200 || dlqDepth > 25) stressLevel = 'critical';

// Under critical stress, shed non-emergency, non-demo load
let action = 'proceed';
let priority = 3;
let shedLoad = false;

if (isEmergency) { priority = 1; action = 'expedite'; }
else if (isDemo) { priority = 2; }
else if (stressLevel === 'critical' && !isEmergency) {
  // Return 503 — do not accept work we cannot process
  shedLoad = true;
  action = 'shed';
}
else if (stressLevel === 'high') { priority = 4; }


