const base_priority = $json.priority || 50;
const age_minutes = $json.age_minutes || 0;
const age_boost = Math.min(age_minutes * 2, 40);
const sla_hours = $json.sla_hours || 24;
const sla_urgency = sla_hours <= 2 ? 30 : sla_hours <= 8 ? 15 : 0;
const risk_penalty = ($json.threat_score || 0) > 40 ? 20 : 0;
const priority_effective = base_priority + age_boost + sla_urgency - risk_penalty;
$json.priority_effective = priority_effective;
return [{
  ...$json,
  stress_level: stressLevel,
  queue_action: action,
  task_priority: priority,
  shed_load: shedLoad,
  backpressure_checked: true
}];

// FIXED GAP 1: Read vps2_status from live database value, not static n8n variable
