const vps2Status = $json.vps2_status || 'healthy'; // Read from DB result below
const recentFailures = parseInt($json.recent_failures || 0);
const failureThreshold = 5;

let circuit = 'closed';
if (recentFailures >= failureThreshold || vps2Status === 'down') circuit = 'open';
if (recentFailures >= 3 && recentFailures < failureThreshold && vps2Status !== 'down') circuit = 'half_open';

const timeoutMultiplier = circuit === 'half_open' ? 0.3 : 1.0;

return [{
