async function send_webhook(url, payload) {
  // Universal connector — works for any external system
  if (!url) return { success: false, error: 'no_webhook_url' };
  try {
    const resp = await $http.request({ method: 'POST', url, body: payload || $json, timeout: 15000 });
    return { success: true, provider: 'universal_webhook', status: resp.status || 200, action: 'send_webhook' };
  } catch(e) {
    return { success: false, error: e.message, action: 'send_webhook' };
  }
}

