// SEC:DecryptForAI — in-memory decryption for AI processing only
// NON-NEGOTIABLE RULES:
//   1. Decrypted values are NEVER written to any database
//   2. Decrypted values are NEVER logged
//   3. Decrypted values are NEVER passed to external integrations (CIL)
//   4. Values exist only during this execution context and downstream AI nodes
//   5. If decryption fails → T5 fallback, customer still receives response

const crypto = require('crypto');

function decrypt(ciphertext, keyHex) {
  if (!ciphertext || !keyHex) return null;
  if (!ciphertext.includes(':')) return null; // not encrypted format
  try {
    const parts = ciphertext.split(':');
    if (parts.length !== 3) return null;
    const [ivHex, tagHex, encHex] = parts;
    const key = Buffer.from(keyHex, 'hex');
    const iv  = Buffer.from(ivHex, 'hex');
    const tag = Buffer.from(tagHex, 'hex');
    const enc = Buffer.from(encHex, 'hex');
    const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
    decipher.setAuthTag(tag);
    return decipher.update(enc, null, 'utf8') + decipher.final('utf8');
  } catch(e) {
    return null; // decryption failure — handled below
  }
}

