const registry = $json.connector_registry || {};

// Map integration types to connector categories
const typeToCategory = {
  'gmail': 'email', 'outlook_email': 'email', 'smtp': 'email',
  'twilio': 'sms', 'messagebird': 'sms',
  'hubspot': 'crm', 'salesforce': 'crm', 'pipedrive': 'crm',
  'google_calendar': 'calendar', 'outlook_calendar': 'calendar',
  'calendly': 'booking', 'acuity': 'booking', 'cal_com': 'booking',
  'stripe': 'payments', 'paypal': 'payments',
  'google_drive': 'storage', 'dropbox': 'storage', 'onedrive': 'storage',
  'webhook': 'webhook',
};

for (const integration of integrations) {
  const category = typeToCategory[integration.integration_type] || integration.integration_type;
  if (integration.has_credentials && integration.status === 'active') {
    registry[category] = {
      provider: integration.provider_name || integration.integration_type,
      status: 'active',
      has_credentials: true,
      reliability_score: integration.reliability_score || 1.0,
    };
  }
}

