const action  = $json.action_type || 'reply';
const registry= $json.connector_registry || {};
const subject = $json.body_decrypted_for_ai || $json.subject || '';
const gatherContext = {};

// Only gather context relevant to the action type — data minimisation principle

// CRM context: look up if sender is a known contact (if CRM configured)
if (registry.crm?.has_credentials && ['reply','crm_write','crm_update'].includes(action)) {
  gatherContext.crm_lookup_requested = true;
  gatherContext.crm_query = { email_hash: $json.sender_email_hash, business_id: bizId };
}

// Calendar context: check availability if booking/scheduling detected in message
const bookingKeywords = ['appointment','book','schedule','availability','meeting','slot','time'];
const hasBookingIntent = bookingKeywords.some(kw => subject.toLowerCase().includes(kw));
if (registry.calendar?.has_credentials && hasBookingIntent) {
  gatherContext.calendar_lookup_requested = true;
}

// Payment context: look for payment/quote intent
const paymentKeywords = ['quote','price','cost','invoice','pay','payment'];
const hasPaymentIntent = paymentKeywords.some(kw => subject.toLowerCase().includes(kw));
if (registry.payments?.has_credentials && hasPaymentIntent) {
  gatherContext.payment_context_requested = true;
}

// Knowledge base context is handled by RAG — don't duplicate here

return [{
  ...$json,
