let userMessage = '';
let ownerNotification = '';

if (reason === 'connector_not_configured') {
  userMessage = 'Thank you for your message. We will get back to you shortly. Reference: ' + ($json.enquiry_id || '');
  ownerNotification = 'ACTION REQUIRED: To respond to this enquiry automatically, configure a ' + ($json.required_connector || 'connector') + ' integration in Settings → Integrations. The enquiry has been saved and awaits your manual response.';
