  ownerNotification = 'Agent ' + ($json.active_agent || '') + ' is not available on your current tier. Upgrade to access this feature.';
  userMessage = 'Thank you for getting in touch. We will respond to your message as soon as possible. Reference: ' + ($json.enquiry_id || '');
