// States: ACT:BUILD -> ACT:VALIDATE -> ACT:GATE -> ACT:APPROVAL -> ACT:EXECUTE -> ACT:OUTCOME -> ACT:REVERSAL
const d = $json;

const action_id = d.action_id || 'ACT-' + require('crypto').randomBytes(8).toString('hex').toUpperCase();
const action_state = d.action_state || 'ACT:BUILD';
const risk_level = d.risk_level || (d.category === 'Emergency support' ? 'high' : 'medium');

// Action contract (v3.3 formal schema)
const action_contract = {
  action_id,
  type: d.action_type || 'response',
  risk_level,
  reversibility: d.reversible === true ? 'reversible' : 'irreversible',
  reversal_possible: d.reversible === true,
  confidence: d.confidence_adjusted || d.confidence || 0,
  source: d.ai_generated ? 'ai' : d.template_used ? 'rule' : 'user',
  state: action_state,
  state_timestamp: new Date().toISOString()
};

// Execution mode routing
const exec_mode = risk_level === 'high' ? 'manual' :
                  risk_level === 'medium' ? 'assisted' :
                  'autonomous';

// State transition — advance to VALIDATE
action_contract.state = 'ACT:VALIDATE';


// v3.3 IMPROVEMENT: User trust layer — every action exposes:
// what_will_happen, why, risk_level, undo_capability
const trust_layer = {
  what_will_happen: d.action_description || d.summary || ('Send ' + (d.action_type || 'response') + ' to ' + (d.recipient || 'recipient')),
  why: d.reasoning || ('Classified as ' + (d.category || 'general') + ', confidence ' + Math.round((d.confidence_adjusted || 0) * 100) + '%'),
  risk_level: risk_level,
  undo_capability: d.reversible === true ? 'Reversible within 5 minutes via dashboard' :
                   d.action_type === 'send_email' ? 'Follow-up correction only — original cannot be recalled' :
                   'Not reversible once executed',
  decision_required: exec_mode !== 'autonomous'
};

return [{ ...d, action_id, action_contract, exec_mode, action_state: 'ACT:VALIDATE', trust_layer }];

const capabilities=$json.capabilities||[];
const actionType=$json.action_type||'reply';
