if((history.booking_intents||0)>3&&!registry.calendar?.has_credentials)s.push({category:'calendar',reason:'Customers ask about bookings. Connect calendar.',priority:2});
if((history.new_customer_enquiries||0)>2&&!registry.crm?.has_credentials)s.push({category:'crm',reason:'New enquiries arriving. Connect CRM to log contacts.',priority:3});
return[{...$json,connector_suggestions:s,connector_discovery:true}];

const patterns=$json.hive_patterns||[];
const suggestions=[];
for(const p of patterns){
  if(p.confidence_score<0.5&&p.occurrence_count>10)
    suggestions.push({type:'response_quality',agent:p.agent_name||'BASTION',
      confidence:p.confidence_score,occurrences:p.occurrence_count,
      suggestion:'Response quality for '+p.category+' is below threshold.',
      requires_owner:true,auto_deploys:false});
  if(p.tier_used==='T5'&&p.occurrence_count>5)
    suggestions.push({type:'ai_coverage',agent:'BASTION',confidence:0.9,
      occurrences:p.occurrence_count,suggestion:'Category '+p.category+' falling back to templates. Check VPS2.',
      requires_owner:true,auto_deploys:false});
}
