// v3.4.3 Extract clean text from HTML — handle empty, JS-only, or failed fetches gracefully
const items = $input.all();
const out = items.map(item => {
  const html = item.json.data || item.json.body || '';
  const business_id = item.json.business_id || $('EKP:Website:SelectPending').item.json.business_id;
  const business_name = $('EKP:Website:SelectPending').item.json.business_name;
  const website_url = $('EKP:Website:SelectPending').item.json.website_url;

  if (!html || html.length < 200) {
    return { json: { business_id, business_name, website_url, scrape_status: 'empty', extracted_text: '', extracted_length: 0 }};
  }

  // Strip script/style/nav/footer/header blocks
  let text = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<nav[\s\S]*?<\/nav>/gi, ' ')
    .replace(/<footer[\s\S]*?<\/footer>/gi, ' ')
    .replace(/<header[\s\S]*?<\/header>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#\d+;/g, '')
    .replace(/\s+/g, ' ')
    .trim();

  // Cap at 8000 chars for Ollama context safety
  const truncated = text.length > 8000;
  if (truncated) text = text.substring(0, 8000);

  // Detect JS-rendered sites (very low text from large HTML = likely React/Vue)
  const ratio = text.length / html.length;
  const likely_js_app = html.length > 5000 && ratio < 0.05;

  return { json: {
    business_id, business_name, website_url,
    scrape_status: text.length < 200 ? 'too_short' : likely_js_app ? 'js_rendered' : 'ok',
    extracted_text: text,
    extracted_length: text.length,
    truncated,
    likely_js_app
  }};
});
return out;

// v3.4.3 Build separate KB draft entries from website analysis
const items = $input.all();
const business_id = $('EKP:Website:Extract').item.json.business_id;
const business_name = $('EKP:Website:Extract').item.json.business_name;
const website_url = $('EKP:Website:Extract').item.json.website_url;
const scrape_status = $('EKP:Website:Extract').item.json.scrape_status;

// If scrape failed, return one explanatory draft so user knows what happened
if (scrape_status !== 'ok') {
  return [{ json: {
    business_id, scrape_status, fallback: true,
    drafts: [{
      title: 'Website read attempt — ' + new Date().toLocaleDateString(),
      content: scrape_status === 'js_rendered'
        ? 'Your website appears to use JavaScript to load content, which Sevari\'s reader cannot see. Please fill out your knowledge base manually — it only takes an hour or two.'
        : 'Sevari could not extract enough text from your website. Please fill out your knowledge base manually.',
      kb_type: 'system_note',
      is_active: false,
      ekp_sourced: true
    }]
  }}];
}

let analysis = {};
try {
  const raw = items[0].json.response || items[0].json.message?.content || '{}';
  analysis = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch(e) {
  return [{ json: { business_id, scrape_status: 'parse_error', drafts: [] }}];
}

const drafts = [];
const dateStr = new Date().toLocaleDateString('en-GB');

if (analysis.services && analysis.services.length) {
  drafts.push({
    title: 'Services (drafted from your website ' + dateStr + ')',
    content: 'Sevari read your website and identified these services. Please review and approve:\n\n' + analysis.services.map(s => '- ' + s).join('\n'),
    kb_type: 'services',
    is_active: false, ekp_sourced: true
  });
}
if (analysis.pricing && analysis.pricing !== 'not on website') {
  drafts.push({
    title: 'Pricing (drafted from your website ' + dateStr + ')',
    content: 'Sevari read your website and noted this about pricing. Please review and approve:\n\n' + analysis.pricing,
    kb_type: 'pricing',
    is_active: false, ekp_sourced: true
  });
}
if (analysis.location_hours && analysis.location_hours !== 'not specified') {
  drafts.push({
    title: 'Location and hours (drafted from your website ' + dateStr + ')',
    content: analysis.location_hours,
    kb_type: 'location',
    is_active: false, ekp_sourced: true
  });
}
if (analysis.policies && analysis.policies !== 'none mentioned') {
  drafts.push({
    title: 'Policies (drafted from your website ' + dateStr + ')',
    content: analysis.policies,
    kb_type: 'policies',
    is_active: false, ekp_sourced: true
  });
}
if (analysis.tone) {
  drafts.push({
    title: 'Voice and tone (drafted from your website ' + dateStr + ')',
    content: 'Based on your website, Sevari understands you sound like this:\n\n' + analysis.tone + '\n\nThis influences how she drafts replies. You can refine this in the My Voice section.',
    kb_type: 'voice',
    is_active: false, ekp_sourced: true
  });
}

return [{ json: { business_id, business_name, scrape_status: 'ok', drafts, draft_count: drafts.length }}];

// v3.4.3 Insert each draft as a separate item — flatten for downstream INSERT
