// v3.4.3 Per-tenant rate limit gate — 30 requests/minute hard cap per business
const result = $input.all();
const original = $('IN:Normalise').item.json;
const requests_count = parseInt(result[0]?.json?.requests_count || 0);
const PER_TENANT_LIMIT = parseInt($vars.SYNC_TENANT_RPM_LIMIT || '30');

if (requests_count > PER_TENANT_LIMIT) {
  return [{ json: {
    ...original,
    tenant_rate_limited: true,
    rejection_reason: 'tenant_rate_limit_exceeded',
    requests_in_window: requests_count,
    limit: PER_TENANT_LIMIT,
    http_status: 429,
    rejected: true
  }}];
}

return [{ json: { ...original, tenant_rate_limited: false, requests_in_window: requests_count }}];

// v3.4.5 URG:Detect — extracts urgency signals from message body+subject
// Runs after classification, before reply generation
// Output: structured urgency object that influences reply generation prompt

const items = $input.all();
const out = items.map(item => {
  const j = item.json;
  const text = ((j.subject || '') + ' ' + (j.body || j.message_body || '')).toLowerCase();

  // Time pressure detection
  const TIME_PATTERNS = [
    { regex: /\b(in\s+)?(\d+)\s*(min|minute|minutes|hr|hour|hours)\b/i, weight: 'high' },
    { regex: /\b(today|tonight|this\s+morning|this\s+afternoon|this\s+evening)\b/i, weight: 'medium' },
    { regex: /\b(asap|right\s+now|immediately|urgent|emergency)\b/i, weight: 'high' },
    { regex: /\b(by\s+\d|before\s+\d|deadline|due\s+by)\b/i, weight: 'medium' },
    { regex: /\b(tomorrow|next\s+day)\b/i, weight: 'low' }
  ];

  let time_pressure = 'none';
  let time_evidence = [];
  for (const p of TIME_PATTERNS) {
    const m = text.match(p.regex);
    if (m) {
      time_evidence.push(m[0]);
      if (p.weight === 'high') time_pressure = 'high';
      else if (p.weight === 'medium' && time_pressure !== 'high') time_pressure = 'medium';
      else if (p.weight === 'low' && time_pressure === 'none') time_pressure = 'low';
    }
  }

  // Stakes detection
  const STAKES_HIGH = ['presentation','meeting','interview','court','exam','wedding','funeral','baby','child','elderly','heating','no heat','frozen','flooding','flooded','emergency','no power','no water','medication','medical'];
  const STAKES_MED = ['client','customer','deadline','project','important','critical','event','party','holiday','travel','flight'];
  const STAKES_LOW = ['planning','considering','thinking about','looking into','wondering','quote'];
  let stakes = 'low';
  let stakes_evidence = [];
  for (const kw of STAKES_HIGH) if (text.includes(kw)) { stakes = 'high'; stakes_evidence.push(kw); }
  if (stakes !== 'high') for (const kw of STAKES_MED) if (text.includes(kw)) { stakes = 'medium'; stakes_evidence.push(kw); }
  if (stakes === 'low') for (const kw of STAKES_LOW) if (text.includes(kw)) { stakes_evidence.push(kw); }

  // Emotional register
  const distress_words = ['help','please','desperate','panic','panicking','stressed','worried','scared','frightened','crying'];
  const calm_words = ['when you have a moment','no rush','whenever','at your convenience'];
  const distress_hits = distress_words.filter(w => text.includes(w)).length;
  const calm_hits = calm_words.filter(w => text.includes(w)).length;
  const exclaim_count = (text.match(/!/g) || []).length;
  let emotional_register = 'neutral';
  if (distress_hits >= 2 || (distress_hits >= 1 && exclaim_count >= 2)) emotional_register = 'distressed';
  else if (distress_hits >= 1 || exclaim_count >= 3) emotional_register = 'concerned';
  else if (calm_hits >= 1) emotional_register = 'calm';

  // Vulnerability indicators
  const vuln_indicators = [];
  if (/\b(child|baby|toddler|infant|newborn)\b/i.test(text)) vuln_indicators.push('child_present');
  if (/\b(elderly|grandma|grandad|grandmother|grandfather|nan|granny)\b/i.test(text)) vuln_indicators.push('elderly_relative');
  if (/\b(disabled|disability|wheelchair|carer|carers)\b/i.test(text)) vuln_indicators.push('disability_mentioned');
  if (/\b(passed away|died|funeral|bereaved|loss of|lost my)\b/i.test(text)) vuln_indicators.push('bereavement');
  if (/\b(unwell|poorly|sick|ill|hospital|operation|surgery)\b/i.test(text)) vuln_indicators.push('illness');

  // Compute deviation_from_normal
  const deviation_from_normal = (
    time_pressure === 'high' ||
    stakes === 'high' ||
    emotional_register === 'distressed' ||
    vuln_indicators.length >= 2
  );

  // Reply guidance for the LLM
  let reply_guidance = '';
  if (deviation_from_normal) {
    const reasons = [];
    if (time_pressure === 'high') reasons.push('explicit time pressure');
    if (stakes === 'high') reasons.push('high stakes situation');
    if (emotional_register === 'distressed') reasons.push('emotional distress');
    if (vuln_indicators.length >= 2) reasons.push('vulnerability indicators');
    reply_guidance = 'IMPORTANT: This message indicates ' + reasons.join(', ') + '. Standard response templates DO NOT APPLY. The reply must (1) acknowledge the urgency or difficulty in the FIRST sentence, (2) offer the FASTEST realistic response, (3) sound human not corporate, (4) NEVER mention generic SLA times like within 24 hours.';
  } else {
    reply_guidance = 'Standard response acceptable. Match business voice and standard SLA expectations from knowledge base.';
  }

  return { json: {
    ...j,
    urgency: {
      time_pressure,
      time_evidence,
      stakes,
      stakes_evidence,
      emotional_register,
      vulnerability_indicators: vuln_indicators,
      deviation_from_normal,
      reply_guidance,
      detected_at: new Date().toISOString()
    }
  }};
});

return out;

// v3.4.5 URG:Apply — modifies SER prompt context based on urgency
const items = $input.all();
return items.map(item => {
  const j = item.json;
  const u = j.urgency || {};

  const urgency_prepend = u.deviation_from_normal
    ? '\n\n[URGENCY DETECTED]\n' + u.reply_guidance + '\n[END URGENCY]\n'
    : '';

  const sms_priority = u.deviation_from_normal ? 'urgent' : 'normal';
  const dashboard_flag = u.deviation_from_normal
    ? { flag: 'urgent', reason: u.reply_guidance.split('.')[0].replace('IMPORTANT: ', '') }
    : null;

  return { json: {
    ...j,
    urgency_prepend,
    sms_priority,
    dashboard_flag,
    priority: u.deviation_from_normal ? 1 : (j.priority || 5)
  }};
});

