// v3.4.6 BG:Pickup — atomically claims one background task
// Uses SKIP LOCKED so multiple workers can run safely in parallel
// Empty result = nothing to do, gracefully exits
const items = $input.all();
if (!items.length || !items[0].json || !items[0].json.task_id) {
  return [{ json: { no_tasks: true } }];
}
const t = items[0].json;
return [{ json: {
  task_id: t.task_id,
  business_id: t.business_id,
  correlation_id: t.correlation_id,
  task_type: t.task_type,
  payload: typeof t.payload === 'string' ? JSON.parse(t.payload) : t.payload,
  attempts: t.attempts || 0,
  picked_up: true
}}];

// v3.4.6 BG:Route — routes claimed task to the correct handler
// Returns a routing decision the IF nodes downstream use
const items = $input.all();
if (!items[0].json.picked_up) return [{ json: { skip: true } }];

const j = items[0].json;
const task_type = j.task_type;
const valid = [
  'hive_pattern_record', 'telemetry_log', 'kb_drift_check', 'health_score_update',
  'compass_signal_process', 'compliance_signal_process', 'rag_weight_adjust', 'feedback_processing'
];

if (!valid.includes(task_type)) {
  return [{ json: { ...j, route: 'unknown', mark_failed: true, fail_reason: 'unknown_task_type:' + task_type }}];
}

return [{ json: { ...j, route: task_type }}];

// v3.4.6 BG:Complete — marks task done, with retry logic for failures
const items = $input.all();
return items.map(item => {
  const j = item.json;
  const succeeded = !j.task_failed;
  const attempts = (j.attempts || 0) + 1;

  let final_status;
  if (succeeded) final_status = 'completed';
  else if (attempts >= (j.max_attempts || 3)) final_status = 'dead';
  else final_status = 'queued';

  return { json: {
    task_id: j.task_id,
    final_status,
    attempts,
    error_detail: j.error_detail || null,
    completed_at: succeeded ? new Date().toISOString() : null,
    retry_at: !succeeded && final_status === 'queued'
      ? new Date(Date.now() + Math.min(60000 * Math.pow(2, attempts), 3600000)).toISOString()
      : null
  }};
});

// v3.4.6 ONB:Route — routes onboarding requests to questions/answer/complete
const items = $input.all();
const j = items[0].json;
const action = j.params?.action || j.body?.action || 'questions';
const business_id = j.headers?.['x-business-id'] || j.body?.business_id;

if (!business_id) {
  return [{ json: { error: 'business_id required', http_status: 400, route: 'error' }}];
}

const valid = ['questions', 'answer', 'complete', 'status'];
if (!valid.includes(action)) {
  return [{ json: { error: 'invalid action: ' + action, http_status: 400, route: 'error' }}];
}

return [{ json: { ...j, business_id, action, route: action }}];

// v3.4.6 ONB:CheckComplete — verifies all required questions answered before go-live
const items = $input.all();
const j = items[0].json;
const required_count = j.required_question_count || 0;
const answered_count = j.answered_count || 0;
const business_id = j.business_id;

if (answered_count < required_count) {
  return [{ json: {
    business_id,
    can_go_live: false,
    answered: answered_count,
    required: required_count,
    blocked_reason: 'incomplete_onboarding',
    missing_count: required_count - answered_count,
    user_message: 'Please answer the remaining ' + (required_count - answered_count) + ' onboarding questions before Sevari can start handling enquiries on your behalf.'
  }}];
}

return [{ json: {
  business_id,
  can_go_live: true,
  answered: answered_count,
  required: required_count,
  user_message: "Onboarding complete. Sevari is ready to start handling your enquiries."
}}];

