// v3.4.6 USAGE:Check — checks task usage against tier limit
// At 80% notify. At 100% notify. At 110% switch to T5-only mode
const items = $input.all();
const j = items[0].json;

const tier = j.tier_name;
const monthly_limit = j.monthly_task_limit;
const tasks_used = j.tasks_used || 0;
const business_id = j.business_id;

// Enterprise / unlimited
if (monthly_limit === null) {
  return [{ json: { ...j, usage_pct: 0, usage_state: 'unlimited', t5_only: false, can_proceed: true }}];
}

const pct = Math.round((tasks_used / monthly_limit) * 100);
let usage_state = 'normal';
let t5_only = false;
let notify = null;

if (pct >= 110) {
  usage_state = 'overage_t5_only';
  t5_only = true;
  if (!j.notify_110_sent_at) notify = 'limit_110';
} else if (pct >= 100) {
  usage_state = 'limit_reached';
  if (!j.notify_100_sent_at) notify = 'limit_100';
} else if (pct >= 80) {
  usage_state = 'approaching_limit';
  if (!j.notify_80_sent_at) notify = 'limit_80';
}

return [{ json: {
  ...j,
  usage_pct: pct,
  usage_state,
  t5_only,
  notify,
  can_proceed: true,  // never block — overage just forces T5
  message_to_log: t5_only
    ? 'Tenant ' + business_id + ' over 110% (' + tasks_used + '/' + monthly_limit + '), serving T5 templates only for remainder of month'
