// v3.4.6 APV:Route — determines which channel/recipient to send approval to
// Reads escalation_state and decides next step
const items = $input.all();
return items.map(item => {
  const j = item.json;
  const state = j.escalation_state || 'primary';
  const method = j.approval_primary_method || 'sms_then_email';
  const fallback_minutes = j.approval_email_fallback_minutes || 15;
  const delegate_timeout_hours = j.delegate_timeout_hours;
  const created_at = new Date(j.approval_created_at || j.created_at);
  const now = new Date();
  const minutes_elapsed = (now - created_at) / 60000;
  const hours_elapsed = minutes_elapsed / 60;

  let next_action = null;
  let next_state = state;
  let send_to_phone = null;
  let send_to_email = null;
  let channel = null;

  if (state === 'primary') {
    // First send — based on user's primary method
    if (method === 'sms_only' || method === 'sms_then_email') {
      send_to_phone = j.approval_primary_phone;
      channel = 'sms_primary';
      next_state = 'primary_email_fallback';  // next escalation if no response
    } else {
      send_to_email = j.approval_primary_email;
      channel = 'email_primary';
      next_state = 'primary_email_fallback';
    }
    next_action = 'send_now';
  } else if (state === 'primary_email_fallback' && minutes_elapsed >= fallback_minutes) {
    // Primary didn't respond in time — try email fallback
    if (method === 'sms_then_email') {
      send_to_email = j.approval_primary_email;
      channel = 'email_primary';
    } else if (method === 'email_then_sms') {
      send_to_phone = j.approval_primary_phone;
      channel = 'sms_primary';
    }
    next_state = j.delegate_phone ? 'delegate_sms' : 'timeout';
    next_action = 'send_now';
  } else if (state === 'delegate_sms' && delegate_timeout_hours && hours_elapsed >= delegate_timeout_hours) {
    // Time to escalate to delegate
    send_to_phone = j.delegate_phone;
    channel = 'sms_delegate';
    next_state = 'delegate_email';
    next_action = 'send_now';
  } else if (state === 'delegate_email' && hours_elapsed >= (delegate_timeout_hours || 0) + 0.5) {
    // Delegate SMS no response — try delegate email
    send_to_email = j.delegate_email;
    channel = 'email_delegate';
    next_state = 'timeout';
    next_action = 'send_now';
  } else {
    next_action = 'wait';
  }

  return { json: {
    ...j,
    next_action,
    next_escalation_state: next_state,
    send_to_phone,
    send_to_email,
    channel,
    minutes_elapsed: Math.round(minutes_elapsed),
    hours_elapsed: hours_elapsed.toFixed(1)
  }};
});

