// v3.4.6 APV:Capture — captures approval response, identifies primary vs delegate
// Locks the decision atomically — first response wins, others ignored
const items = $input.all();
return items.map(item => {
  const j = item.json;
  const decision = j.decision || j.approve_or_reject;
  const responder_phone = j.responder_phone;
  const responder_email = j.responder_email;
  const approval_token = j.approval_token;

  // Identify role
  let approved_by = null;
  let approved_by_role = null;

  if (responder_phone === j.approval_primary_phone || responder_email === j.approval_primary_email) {
    approved_by = j.approval_primary_email;
    approved_by_role = 'primary';
  } else if (responder_phone === j.delegate_phone || responder_email === j.delegate_email) {
    approved_by = j.delegate_email;
    approved_by_role = 'delegate';
  } else {
    return { json: { error: 'Unrecognised responder', http_status: 403 }};
  }

  const requires_second_step = approved_by_role === 'delegate' && j.is_financial_action === true;

  return { json: {
    approval_token,
    decision,
    approved_by,
    approved_by_role,
    requires_second_step_confirmation: requires_second_step,
    primary_should_be_notified: approved_by_role === 'delegate',
    decision_locked_at: new Date().toISOString()
  }};
});

