  const adjustments = {
    'factually_wrong': { delta: -0.15, reason: 'KB content produced factually wrong reply' },
    'tone_off': { delta: -0.05, reason: 'KB content produced reply with wrong tone' },
    'too_long': { delta: -0.02, reason: 'KB content led to overlong reply' },
    'too_short': { delta: -0.02, reason: 'KB content led to under-detailed reply' },
    'missing_info': { delta: -0.10, reason: 'KB lacking content needed for complete reply' },
    'wrong_action': { delta: -0.20, reason: 'KB content led to wrong recommended action' },
    'sounded_generic': { delta: -0.08, reason: 'KB content too generic for tenant voice' },
    'other': { delta: -0.05, reason: 'Generic rejection feedback' }
  };

  const adj = adjustments[reason] || adjustments['other'];

  return { json: {
    business_id: j.business_id,
    kb_entry_ids: j.kb_entries_used || [],  // populated from RAG retrieval log
