// v3.4.6 STATS:Build — assembles tenant stats response from materialised view + live queries
const items = $input.all();
const j = items[0].json;
const business_id = j.business_id;

// Aggregate the by-hour materialised view rows into single response
const hourly = items.map(i => i.json).filter(r => r.business_id === business_id);

const total = hourly.reduce((s, r) => s + (r.enquiries_handled || 0), 0);
const ai = hourly.reduce((s, r) => s + (r.handled_by_ai || 0), 0);
const tpl = hourly.reduce((s, r) => s + (r.handled_by_template || 0), 0);
const esc = hourly.reduce((s, r) => s + (r.escalated_to_user || 0), 0);

// Find busiest hour
const busy_hour = hourly.reduce((max, r) =>
  (r.enquiries_handled > (max.enquiries_handled || 0)) ? r : max,
  hourly[0] || {});

const avg_response = total > 0
  ? Math.round(hourly.reduce((s, r) => s + ((r.avg_response_ms || 0) * (r.enquiries_handled || 0)), 0) / total)
  : 0;

const resolution_rate = total > 0 ? Math.round(((total - esc) / total) * 100) : 100;

return [{ json: {
  business_id,
  period: 'last_30_days',
  enquiries_handled: total,
  handled_by_ai: ai,
  handled_by_template: tpl,
  escalated_to_user: esc,
  resolution_rate_pct: resolution_rate,
  avg_response_ms: avg_response,
  avg_response_seconds: (avg_response / 1000).toFixed(1),
  busiest_hour_24h: busy_hour.busy_hour,
  channels_used: hourly[0]?.channels_used || 0,
  most_recent_enquiry: hourly[0]?.most_recent_enquiry,
  generated_at: new Date().toISOString(),
  // The story for the user
  user_summary: total > 0
    ? `Sevari handled ${total} enquiries this month with a ${(avg_response/1000).toFixed(1)}-second average response time. ${resolution_rate}% were resolved without needing your direct attention.`
    : `Sevari is set up and ready. Once enquiries start coming in, your stats will appear here.`
}}];

// v3.4.6 TRACE:Init — generates correlation_id at intake, records start
const crypto = require('crypto');
const items = $input.all();
return items.map(item => {
  const j = item.json;
  const correlation_id = j.correlation_id || crypto.randomUUID();
  const intake_started_at = Date.now();
  return { json: {
    ...j,
    correlation_id,
    intake_started_at,
    _trace_marks: { intake_started_at }
  }};
});

// v3.4.6 TRACE:Mark — records stage timestamp; reusable wherever needed
// Called via Set node parameters: set _trace_marks.<stage> = Date.now()
// Final aggregation done by TRACE:Finalize
const items = $input.all();
return items.map(item => {
  const j = item.json;
  const stage = j._next_mark || 'unknown';
  const now = Date.now();
  const marks = j._trace_marks || {};
  marks[stage] = now;
  return { json: { ...j, _trace_marks: marks }};
});

// v3.4.6 TRACE:Finalize — at end of pipeline, computes per-stage durations + total
const items = $input.all();
return items.map(item => {
  const j = item.json;
  const m = j._trace_marks || {};
  const intake_start = m.intake_started_at || j.intake_started_at;

  const timing = {
    timing_intake_ms: m.intake_complete ? m.intake_complete - intake_start : null,
    timing_guardian_ms: m.guardian_complete && m.guardian_start ? m.guardian_complete - m.guardian_start : null,
    timing_identity_ms: m.identity_complete && m.identity_start ? m.identity_complete - m.identity_start : null,
    timing_classify_ms: m.classify_complete && m.classify_start ? m.classify_complete - m.classify_start : null,
    timing_rag_ms: m.rag_complete && m.rag_start ? m.rag_complete - m.rag_start : null,
    timing_inference_ms: m.inference_complete && m.inference_start ? m.inference_complete - m.inference_start : null,
    timing_output_ms: m.output_complete && m.output_start ? m.output_complete - m.output_start : null,
    timing_total_ms: Date.now() - intake_start
  };

  return { json: { ...j, ...timing, correlation_id: j.correlation_id }};
});

// v3.4.6 LOG:Emit — emits a structured log entry to pipeline_log via background queue
// Fire and forget; never blocks critical path
const items = $input.all();
return items.map(item => {
  const j = item.json;
  return { json: {
    correlation_id: j.correlation_id,
    business_id: j.business_id,
    stage: j._log_stage || 'unknown',
    event: j._log_event || 'unknown',
    detail: JSON.stringify(j._log_detail || {}),
    duration_ms: j._log_duration_ms || null,
    queued_at: new Date().toISOString()
  }};
});

// v3.4.6 HEALTH:Score — computes green/amber/red health for each tenant
// Scheduled run (daily); evaluates churn signals
const items = $input.all();
return items.map(item => {
  const j = item.json;
  const business_id = j.business_id;

  // Signals (negative = churn risk)
  const enquiry_volume_trend = parseFloat(j.enquiry_volume_trend || 0);  // % change vs prior period
  const approval_response_time_trend = parseFloat(j.approval_response_time_trend || 0); // % change in time-to-approve
  const kb_freshness_days = parseInt(j.kb_freshness_days || 0);
  const escalation_rate = parseFloat(j.escalation_rate || 0); // % of enquiries hitting T6
  const last_login_days_ago = parseInt(j.last_login_days_ago || 0);

  // Score weights (sum can exceed thresholds)
  let risk_score = 0;
  const reasons = [];

  if (enquiry_volume_trend < -30) { risk_score += 2; reasons.push('enquiry volume dropped >30%'); }
  else if (enquiry_volume_trend < -15) { risk_score += 1; reasons.push('enquiry volume dropping'); }

  if (approval_response_time_trend > 50) { risk_score += 2; reasons.push('approval response time slower'); }
  else if (approval_response_time_trend > 25) { risk_score += 1; reasons.push('approval response time creeping up'); }

  if (kb_freshness_days > 60) { risk_score += 2; reasons.push('KB not updated in 60+ days'); }
  else if (kb_freshness_days > 30) { risk_score += 1; reasons.push('KB ageing'); }

  if (escalation_rate > 30) { risk_score += 2; reasons.push('high T6 escalation rate'); }
  else if (escalation_rate > 15) { risk_score += 1; reasons.push('moderate T6 escalation rate'); }

  if (last_login_days_ago > 14) { risk_score += 2; reasons.push('not logged in for 14+ days'); }
  else if (last_login_days_ago > 7) { risk_score += 1; reasons.push('infrequent dashboard visits'); }

  let health_score;
  if (risk_score >= 5) health_score = 'red';
  else if (risk_score >= 2) health_score = 'amber';
  else health_score = 'green';

  return { json: {
    business_id,
    health_score,
    risk_score,
    enquiry_volume_trend,
    approval_response_time_trend,
    kb_freshness_days,
    escalation_rate,
    last_login_days_ago,
    risk_reasons: reasons,
    computed_at: new Date().toISOString()
  }};
});

// v3.4.6 HEALTH:Outreach — composes proactive outreach for amber/red tenants
// Only sends if not contacted in last 14 days for the same level
const items = $input.all();
return items.map(item => {
  const j = item.json;
  const score = j.health_score;
  if (score === 'green') return { json: { skip: true }};

  const recent_outreach = j.retention_outreach_sent_at &&
    (Date.now() - new Date(j.retention_outreach_sent_at).getTime()) < (14 * 24 * 60 * 60 * 1000);
  if (recent_outreach) return { json: { skip: true }};

  let subject, body, method;
  if (score === 'amber') {
    subject = "How's Sevari working out for you?";
    body = `Hi,\n\nI've noticed a few things in your Sevari usage that made me want to check in:\n\n${j.risk_reasons.map(r => '• ' + r).join('\n')}\n\nNothing's wrong. I just wanted to ask: how's it going? Is there anything that's not working the way you expected? Anything we could improve?\n\nReply to this email and it reaches me directly. No script. No template. Just me.\n\n— Dan\nveylithsystems@gmail.com`;
    method = 'email';
  } else {
    subject = 'Quick check-in from Veylith Systems';
    body = `Hi,\n\nI noticed it's been a while since you've been active on Sevari. I wanted to make sure everything's okay and that there's nothing I can help with.\n\nSometimes the best thing for a tenant is a quick adjustment to how Sevari is configured — operating mode, KB content, channel setup. Other times it's just life getting busy.\n\nEither way, if there's anything I can do, reply to this email. It reaches me directly.\n\nIf Sevari isn't working for you any more, I'd genuinely like to know why. No hard sell — just an honest conversation.\n\n— Dan\nveylithsystems@gmail.com`;
    method = 'email';
  }

  return { json: {
    business_id: j.business_id,
    to_email: j.contact_email,
    subject,
    body_text: body,
    body_html: body.replace(/\n/g, '<br>'),
    notification_type: 'retention_outreach_' + score,
    health_score_at_send: score,
    queued_at: new Date().toISOString()
  }};
});

