// v3.4.6 COMPASS-INTERNAL:Select — picks next due source to scrape
const items = $input.all();
if (!items.length || !items[0].json || !items[0].json.source_id) {
  return [{ json: { no_sources_due: true }}];
}
return [{ json: items[0].json }];

// v3.4.6 COMPASS-INTERNAL:Parse — parses scraped content based on method
const items = $input.all();
return items.map(item => {
  const j = item.json;
  const method = j.scrape_method;
  const raw = j.data || j.body || '';

  let signals = [];

  try {
    if (method === 'rss') {
      // Parse RSS — extract <item>...</item> entries
      const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
      let match;
      let count = 0;
      while ((match = itemRegex.exec(raw)) !== null && count < 20) {
        const itemBlock = match[1];
        const titleMatch = itemBlock.match(/<title[^>]*>(?:<!\[CDATA\[)?([^<\]]+)(?:\]\]>)?<\/title>/i);
        const linkMatch = itemBlock.match(/<link[^>]*>([^<]+)<\/link>/i);
        const descMatch = itemBlock.match(/<description[^>]*>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/description>/i);
        if (titleMatch) {
          signals.push({
            title: titleMatch[1].trim(),
            url: linkMatch ? linkMatch[1].trim() : null,
            summary: descMatch ? descMatch[1].replace(/<[^>]+>/g, '').substring(0, 500).trim() : null
          });
        }
        count++;
      }
    } else if (method === 'api') {
      // Hacker News / similar JSON APIs
      const data = typeof raw === 'string' ? JSON.parse(raw) : raw;
      const hits = data.hits || data.items || [];
      signals = hits.slice(0, 20).map(h => ({
        title: h.title || h.story_title || '',
        url: h.url || h.story_url || ('https://news.ycombinator.com/item?id=' + (h.objectID || h.id)),
        summary: (h.story_text || h.comment_text || h.story_title || '').substring(0, 500)
      })).filter(s => s.title);
    } else if (method === 'html') {
      // Best-effort HTML parsing — extract h1/h2/h3 with nearby a-tags
      const headlineRegex = /<(h[123])[^>]*>([\s\S]*?)<\/\1>/gi;
      let match;
      let count = 0;
      while ((match = headlineRegex.exec(raw)) !== null && count < 20) {
        const headline = match[2].replace(/<[^>]+>/g, '').trim();
        if (headline.length > 10 && headline.length < 200) {
          signals.push({ title: headline, url: j.source_url, summary: null });
          count++;
        }
      }
    }
  } catch (e) {
    return { json: { error: 'parse_failed', error_detail: e.message, source_id: j.source_id }};
  }

  return { json: {
    source_id: j.source_id,
    source_category: j.source_category,
    source_name: j.source_name,
    signals,
    parsed_count: signals.length
  }};
});

// v3.4.6 COMPASS-INTERNAL:Score — calls Ollama to score each signal's materiality
// Output is consumed by Ollama HTTP node downstream
const items = $input.all();
const item = items[0].json;
const signals = item.signals || [];
if (!signals.length) return [{ json: { no_signals: true }}];

// Build prompt for Ollama batch scoring
const prompt = `You are a strategic intelligence analyst for Veylith Systems, a UK SaaS company building Sevari (an AI customer-service platform for SMBs) and Sentinel (an AI assistant for police call handlers).

Score each signal below for materiality to Veylith Systems on 0.0 to 1.0:
- 0.0-0.3: not relevant, generic noise
- 0.4-0.6: tangentially relevant
- 0.7-0.8: directly relevant — competitor news, customer pain points, regulatory developments
- 0.9-1.0: critical — directly affects roadmap, threats, opportunities

Source: ${item.source_name} (${item.source_category})

Signals:
${signals.map((s, i) => (i+1) + '. ' + s.title).join('\n')}

Return JSON array — one object per signal:
[{"index": 1, "score": 0.75, "reason": "describes Intercom Fin pricing change"}, ...]
JSON only, no commentary.`;

return [{ json: {
  source_id: item.source_id,
  source_category: item.source_category,
  source_name: item.source_name,
  signals,
  ollama_prompt: prompt
}}];

// v3.4.6 COMPASS-INTERNAL:Persist — stores scored signals with materiality
const items = $input.all();
const j = items[0].json;
const signals = j.signals || [];
const ollamaResp = j.ollama_response || j.body?.response || j.response || '[]';

let scores = [];
try {
  const parsed = typeof ollamaResp === 'string' ? JSON.parse(ollamaResp) : ollamaResp;
  scores = Array.isArray(parsed) ? parsed : (parsed.scores || []);
} catch (e) {
  // Fall back to default scores
  scores = signals.map((s, i) => ({ index: i+1, score: 0.5, reason: 'scoring_failed' }));
}

// Match scores to signals
const out = signals.map((sig, i) => {
  const score = scores.find(s => s.index === (i+1)) || { score: 0.5, reason: 'no_score' };
  return {
    json: {
      source_id: j.source_id,
      source_category: j.source_category,
      signal_title: sig.title,
      signal_url: sig.url,
      signal_summary: sig.summary,
      materiality_score: parseFloat(score.score) || 0.5,
      materiality_reason: score.reason,
      ingested_at: new Date().toISOString()
    }
  };
});

return out;

