// v3.4.6 COMP:GapAnalysis — for material signals, compare against current docs
// Triggered only when materiality >= 0.7
const items = $input.all();
const item = items[0].json;
const signal = item.signal;
const docs = item.docs || [];

if (!signal || signal.materiality_score < 0.7 || docs.length === 0) {
  return [{ json: { skip: true }}];
}

// Build prompt: "given this regulatory development, what in our docs needs review?"
const prompt = `You are a UK data protection compliance analyst.

A new regulatory signal has been received:

TITLE: ${signal.signal_title}
CLASSIFICATION: ${signal.signal_classification}
SUMMARY: ${signal.signal_summary || 'No summary available'}
TOPICS: ${(signal.topics || []).join(', ')}
JURISDICTIONS: ${(signal.jurisdictions || []).join(', ')}

Current Veylith Systems compliance documents:

${docs.map(d => '--- ' + d.doc_type.toUpperCase() + ' (v' + d.doc_version + ') ---\n' + d.doc_content.substring(0, 2000) + '...\n').join('\n')}

For each affected document, output:
- doc_type: which document
- gap_summary: one sentence — what specifically may need updating
- recommended_action: 1-2 sentences — what should change
- draft_amendment: a clear text amendment, ready for solicitor review
- severity: informational | minor | significant | critical

Return JSON array. JSON only, no commentary. If no documents are affected, return [].`;

return [{ json: {
  signal_id: signal.signal_id,
  ollama_prompt: prompt,
  docs_reviewed: docs.length
}}];

// v3.4.6 COMP:PersistGaps — stores gap analysis output as compliance_gaps records
const items = $input.all();
const item = items[0].json;
const signal_id = item.signal_id;
const ollamaResp = item.ollama_response || item.body?.response || item.response || '[]';

let gaps = [];
try {
  const parsed = typeof ollamaResp === 'string' ? JSON.parse(ollamaResp) : ollamaResp;
  gaps = Array.isArray(parsed) ? parsed : [];
} catch(e) {
  return [{ json: { parse_failed: true, signal_id }}];
}

if (gaps.length === 0) return [{ json: { no_gaps_detected: true, signal_id }}];

return gaps.map(g => ({
  json: {
    signal_id,
    affected_doc_type: g.doc_type,
    gap_summary: g.gap_summary,
    recommended_action: g.recommended_action,
    draft_amendment: g.draft_amendment,
    severity: g.severity || 'informational',
    status: 'pending_review',
    detected_at: new Date().toISOString()
  }
}));

const crypto = require('crypto');
const sig = $json.headers['stripe-signature'] || $json.headers['Stripe-Signature'] || '';
const secret = $vars.STRIPE_WEBHOOK_SECRET || '';
const rawBody = typeof $json.body === 'string' ? $json.body : JSON.stringify($json.body || {});
if (!sig || !secret) return [{ verified:false, error:'missing_signature_or_secret' }];
const parts = sig.split(',').reduce((a,p)=>{const[k,v]=p.split('=');a[k]=v;return a;},{});
const ts = parts.t; const expected = parts.v1;
if (!ts || !expected) return [{ verified:false, error:'malformed' }];
if (Math.floor(Date.now()/1000) - parseInt(ts) > 300) return [{ verified:false, error:'too_old' }];
const computed = crypto.createHmac('sha256', secret).update(ts+'.'+rawBody).digest('hex');
let diff=0; for (let i=0;i<computed.length;i++) diff |= computed.charCodeAt(i) ^ expected.charCodeAt(i);
if (computed.length !== expected.length || diff !== 0) return [{ verified:false, error:'sig_invalid' }];
return [{ ...$json, verified:true, stripe_event:$json.body }];

const crypto=require('crypto');
const apiKey=$vars.MAILGUN_API_KEY||'';
const ts=$json.body['timestamp']||''; const token=$json.body['token']||''; const sig=$json.body['signature']||'';
if(!apiKey||!ts||!token||!sig) return [{verified:false}];
if(crypto.createHmac('sha256',apiKey).update(ts+token).digest('hex')!==sig) return [{verified:false}];
return [{verified:true, channel:'email',
  subject:$json.body['subject']||'',
  body:$json.body['stripped-text']||$json.body['body-plain']||'',
  sender_email:$json.body['sender']||'',
  recipient_email:$json.body['recipient']||'',
  sender_name:$json.body['from']||$json.body['sender']||''}];

const crypto=require('crypto');
const masterKey=$vars.SYNC_PII_KEY||'';
const creds=JSON.stringify($json.body.credentials||{});
const iv=crypto.randomBytes(12);
const c=crypto.createCipheriv('aes-256-gcm',Buffer.from(masterKey,'hex'),iv);
const enc=Buffer.concat([c.update(creds,'utf8'),c.final()]);
const tag=c.getAuthTag();
return [{...$json, credentials_encrypted: iv.toString('hex')+':'+tag.toString('hex')+':'+enc.toString('hex')}];

const adminKey=$json.headers['x-admin-key']||'';
const expected=$vars.SYNC_ADMIN_KEY_HASH||'';
const computed=require('crypto').createHash('sha256').update(adminKey).digest('hex');
return [{...$json, admin_authed: computed===expected}];

// DLV:DecryptRecipient — mirror of SEC:EncryptPII. Decrypt ONLY at moment of send.
const crypto = require('crypto');
const key = $vars.SYNC_PII_KEY || '';
function decrypt(blob){
  if(!blob || !key || String(blob).indexOf(':')<0) return '';
  try{
    const [iv,tag,enc]=String(blob).split(':');
    const d=crypto.createDecipheriv('aes-256-gcm',Buffer.from(key,'hex'),Buffer.from(iv,'hex'));
    d.setAuthTag(Buffer.from(tag,'hex'));
    return Buffer.concat([d.update(Buffer.from(enc,'hex')),d.final()]).toString('utf8');
  }catch(e){ return ''; }
}
const j=$json;
const recipient_email = decrypt(j.sender_email_encrypted);
return [{ json: { ...j,
  recipient_email,
  recipient_mobile: j.recipient_mobile || j.from_phone || '',
  final_output: j.final_output || j.response_text || '',
  delivery_status: 'ready_to_send'
}}];

const j=$input.first().json;
const phase=parseInt(j.phase)||1;
const types=['problem_post','education_post','proof_post','milestone_post'];
const contentType=j.content_type||types[new Date().getDay()%4];
const phaseNote={1:'Focus on founder pain points only. No product mentions.',
  2:'Hint at AI-powered autonomous operations as a solution category. No product name.',
  3:'You may reference Sevari by name. Keep claims concrete and credible.'}[phase]||'Focus on founder pain points.';
const typeNote={
  problem_post:'Write a punchy LinkedIn post (120-180 words) about a specific daily operational pain point SMB founders face.',
  education_post:'Write an educational LinkedIn post (150-200 words) with one practical operational tip for SMB founders.',
  proof_post:'Write a credibility post (130-170 words) describing a realistic operational efficiency outcome.',
  milestone_post:'Write a milestone update (100-150 words) building brand credibility around building autonomous operations software.'}[contentType];
return [{json:{...j,
  herald_system_prompt:'You are a content strategist for Veylith Systems, a UK AI company. Write for LinkedIn. Tone: professional, direct, no fluff. Max 3 hashtags. '+phaseNote,
  herald_user_prompt:typeNote+' Output ONLY the post text.',
  herald_content_type:contentType, herald_phase:phase,
  model_name:'llama3.2:3b', timeout_ms:60000}}];

const j=$input.first().json;
const vps2=$vars.SYNC_VPS2_HOST||'http://localhost:11434';
const chain=['llama3.2:3b','mistral:7b-instruct-q4_K_M','phi3:mini'];
const statics={
  problem_post:'Running a business means wearing every hat at once. Most founders spend 3+ hours daily on tasks that could run autonomously. The cost is never the software — it is the time you cannot get back. What would you do with 3 extra hours a day? #SMB #Founder #Productivity',
  education_post:'One operational change that compounds fast: build a triage system for inbound messages. Categorise by urgency, route by type, respond by template. Done in a week — saves 45 minutes daily. Small systems create big margins. #SMBOperations #Automation',
  proof_post:'A founder we spoke with was manually chasing 12 invoices a month — 4 hours of focus time gone. Automated follow-up at day 7, 14 and 21 resolved 9 of 12 without a single manual touchpoint. #CashFlow #SMB #Automation',
  milestone_post:'Building in public: autonomous enquiry handling, daily executive briefings and compliance gap monitoring shipped this sprint. Every feature designed to remove a founder task, not add a dashboard to check. #BuildingInPublic #AI #Veylith'};
let generated=null,model_used=null;
for(const model of chain){
  try{
    const r=await $http.request({method:'POST',url:vps2+'/api/chat',
      body:{model,messages:[
        {role:'system',content:j.herald_system_prompt},
        {role:'user',content:j.herald_user_prompt}
      ],stream:false,options:{temperature:0.7,num_predict:300,num_ctx:2048}},
      timeout:j.timeout_ms||60000});
    const out=r.message?.content||r.choices?.[0]?.message?.content||'';
    if(out&&out.trim().length>40){generated=out.trim();model_used=model;break;}
  }catch(e){continue;}
}
if(!generated){generated=statics[j.herald_content_type]||statics['education_post'];model_used='static_fallback';}
return [{json:{...j,herald_content:generated,herald_model_used:model_used,herald_generated_at:new Date().toISOString()}}];

